    { const char * tb_v908 = "TB_API void *bsearch(const void *key, const void *base, size_t n, size_t size, int (*cmp)(const void *, const void *)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v908; }
    { const char * tb_v909 = "    size_t lo = 0, hi = n;\n"; *(const char * *)tb_grow(v_lines) = tb_v909; }
    { const char * tb_v910 = "    while (lo < hi) {\n"; *(const char * *)tb_grow(v_lines) = tb_v910; }
