    { const char * tb_v1009 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1009; }
    { const char * tb_v1010 = "TB_API void tb_set_fs(unsigned char *tp) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1010; }
    { const char * tb_v1011 = "    uint64_t v = (uint64_t)(uintptr_t)tp;\n"; *(const char * *)tb_grow(v_lines) = tb_v1011; }
    { const char * tb_v1012 = "    __asm__ volatile(\"wrmsr\" : : \"c\"(0xC0000100u), \"a\"((uint32_t)v), \"d\"((uint32_t)(v >> 32)) : \"memory\");\n"; *(const char * *)tb_grow(v_lines) = tb_v1012; }
