    { const char * tb_v3891 = "        uintptr_t lo = b->a - sizeof(tb_memh), hi = b->a + b->n + TB_MEM_GUARD;\n"; *(const char * *)tb_grow(v_lines) = tb_v3891; }
    { const char * tb_v3892 = "        if (a + n <= lo || a >= hi) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v3892; }
    { const char * tb_v3893 = "        if (!b->live) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3893; }
    { const char * tb_v3894 = "            char buf[160];\n"; *(const char * *)tb_grow(v_lines) = tb_v3894; }
    { const char * tb_v3895 = "            snprintf(buf, sizeof buf, \"эта память уже освобождена: free_mem в строке %d\", b->fline);\n"; *(const char * *)tb_grow(v_lines) = tb_v3895; }
    { const char * tb_v3896 = "            tb_mem_die(line, buf, b->line);\n"; *(const char * *)tb_grow(v_lines) = tb_v3896; }
    { const char * tb_v3897 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v3897; }
    { const char * tb_v3898 = "        if (a < b->a || a + n > b->a + b->n) tb_mem_die(line, \"чтение или запись за краем блока\", b->line);\n"; *(const char * *)tb_grow(v_lines) = tb_v3898; }
    { const char * tb_v3899 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3899; }
    { const char * tb_v3900 = "    tb_mem_unlock();\n"; *(const char * *)tb_grow(v_lines) = tb_v3900; }
    { const char * tb_v3901 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3901; }
    { const char * tb_v3902 = "static tb_memb *tb_mem_find(uintptr_t a) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3902; }
    { const char * tb_v3903 = "    for (long long i = tb_mem_n - 1; i >= 0; i--) if (tb_mem_all[i].a == a) return &tb_mem_all[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v3903; }
    { const char * tb_v3904 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3904; }
    { const char * tb_v3905 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3905; }
    { const char * tb_v3906 = "// чтение и запись по адресу: volatile — компилятор C не выкинет и не переставит их\n"; *(const char * *)tb_grow(v_lines) = tb_v3906; }
    { const char * tb_v3907 = "#define TB_TOUCH(a, n) if (TB_RARE(tb_memchk())) tb_mem_touch((uintptr_t)(a), (n), line)\n"; *(const char * *)tb_grow(v_lines) = tb_v3907; }
    { const char * tb_v3908 = "TB_INL long long tb_rd8(long long a, int line) { TB_TOUCH(a, 1); return *(volatile uint8_t *)(uintptr_t)a; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3908; }
