    { const char * tb_v4026 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v4026; }
    { const char * tb_v4027 = "// текст из C: копия в память Tachbit (C может потом поменять или отдать свой); NULL → \"\"\n"; *(const char * *)tb_grow(v_lines) = tb_v4027; }
    { const char * tb_v4028 = "TB_API const char *tb_ctext(const char *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4028; }
    { const char * tb_v4029 = "    if (!p) return \"\";\n"; *(const char * *)tb_grow(v_lines) = tb_v4029; }
    { const char * tb_v4030 = "    size_t n = strlen(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v4030; }
