    { const char * tb_v5227 = "// все картинки программы: точки подряд в одном большом массиве (его же видит видеокарта)\n"; *(const char * *)tb_grow(v_lines) = tb_v5227; }
    { const char * tb_v5228 = "typedef struct { int w, h; uint32_t off; } tb_image;\n"; *(const char * *)tb_grow(v_lines) = tb_v5228; }
