    { const char * tb_v5232 = "TB_API size_t tb_imgpx_n = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5232; }
    { const char * tb_v5233 = "// картинка из байтов в памяти (PNG, JPEG, BMP, GIF) → номер картинки; -1 и tb_err — не вышло\n"; *(const char * *)tb_grow(v_lines) = tb_v5233; }
    { const char * tb_v5234 = "TB_API long long tb_image_add(const unsigned char *d, size_t sz) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5234; }
