    { const char * tb_v5263 = "// image_from_mem(адрес, байт): картинка из памяти (файл прочитан со своего диска, пришёл по сети ...)\n"; *(const char * *)tb_grow(v_lines) = tb_v5263; }
    { const char * tb_v5264 = "TB_API long long tb_image_from_mem(long long a, long long n, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5264; }
    { const char * tb_v5265 = "    (void)line;\n"; *(const char * *)tb_grow(v_lines) = tb_v5265; }
