    { const char * tb_v5269 = "// image_scaled(картинка, w, h): новая картинка другого размера (уменьшение — среднее по площади,\n"; *(const char * *)tb_grow(v_lines) = tb_v5269; }
    { const char * tb_v5270 = "// увеличение — ближайшая точка). Так фото с диска влезает в окно, значок — в свой квадрат.\n"; *(const char * *)tb_grow(v_lines) = tb_v5270; }
    { const char * tb_v5271 = "TB_API long long tb_image_scaled(long long i, long long w, long long h) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5271; }
    { const char * tb_v5272 = "    if (i < 0 || i >= tb_nimg) { tb_err = \"нет такой картинки\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5272; }
    { const char * tb_v5273 = "    if (w < 1 || h < 1 || w * h > (1ll << 26)) { tb_err = \"такой размер не годится\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5273; }
    { const char * tb_v5274 = "    int sw = tb_imgs[i].w, sh = tb_imgs[i].h;\n"; *(const char * *)tb_grow(v_lines) = tb_v5274; }
    { const char * tb_v5275 = "    size_t need = tb_imgpx_n + (size_t)w * h;\n"; *(const char * *)tb_grow(v_lines) = tb_v5275; }
    { const char * tb_v5276 = "    if (need > 0xFFFFFFFFu) { tb_err = \"слишком много картинок\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5276; }
    { const char * tb_v5277 = "    uint32_t *all = realloc(tb_imgpx, need * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v5277; }
    { const char * tb_v5278 = "    if (all) tb_imgpx = all;\n"; *(const char * *)tb_grow(v_lines) = tb_v5278; }
    { const char * tb_v5279 = "    tb_image *list = realloc(tb_imgs, (size_t)(tb_nimg + 1) * sizeof(tb_image));\n"; *(const char * *)tb_grow(v_lines) = tb_v5279; }
    { const char * tb_v5280 = "    if (list) tb_imgs = list;\n"; *(const char * *)tb_grow(v_lines) = tb_v5280; }
    { const char * tb_v5281 = "    if (!all || !list) { tb_err = \"не хватило памяти\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5281; }
    { const char * tb_v5282 = "    const uint32_t *src = tb_imgpx + tb_imgs[i].off;\n"; *(const char * *)tb_grow(v_lines) = tb_v5282; }
    { const char * tb_v5283 = "    uint32_t *dst = tb_imgpx + tb_imgpx_n;\n"; *(const char * *)tb_grow(v_lines) = tb_v5283; }
    { const char * tb_v5284 = "    for (long long y = 0; y < h; y++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5284; }
    { const char * tb_v5285 = "        int y0 = (int)(y * sh / h), y1 = (int)((y + 1) * sh / h);\n"; *(const char * *)tb_grow(v_lines) = tb_v5285; }
    { const char * tb_v5286 = "        if (y1 <= y0) y1 = y0 + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5286; }
    { const char * tb_v5287 = "        for (long long x = 0; x < w; x++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5287; }
    { const char * tb_v5288 = "            int x0 = (int)(x * sw / w), x1 = (int)((x + 1) * sw / w);\n"; *(const char * *)tb_grow(v_lines) = tb_v5288; }
    { const char * tb_v5289 = "            if (x1 <= x0) x1 = x0 + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5289; }
    { const char * tb_v5290 = "            unsigned long long a = 0, r = 0, g = 0, b = 0, n = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5290; }
    { const char * tb_v5291 = "            for (int yy = y0; yy < y1; yy++)\n"; *(const char * *)tb_grow(v_lines) = tb_v5291; }
    { const char * tb_v5292 = "                for (int xx = x0; xx < x1; xx++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5292; }
    { const char * tb_v5293 = "                    uint32_t c = src[(size_t)yy * sw + xx];\n"; *(const char * *)tb_grow(v_lines) = tb_v5293; }
    { const char * tb_v5294 = "                    a += c >> 24; r += c >> 16 & 255; g += c >> 8 & 255; b += c & 255; n++;\n"; *(const char * *)tb_grow(v_lines) = tb_v5294; }
    { const char * tb_v5295 = "                }\n"; *(const char * *)tb_grow(v_lines) = tb_v5295; }
    { const char * tb_v5296 = "            dst[(size_t)y * w + x] = (uint32_t)(a / n) << 24 | (uint32_t)(r / n) << 16 | (uint32_t)(g / n) << 8 | (uint32_t)(b / n);\n"; *(const char * *)tb_grow(v_lines) = tb_v5296; }
    { const char * tb_v5297 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v5297; }
    { const char * tb_v5298 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5298; }
    { const char * tb_v5299 = "    tb_imgs[tb_nimg].w = (int)w; tb_imgs[tb_nimg].h = (int)h; tb_imgs[tb_nimg].off = (uint32_t)tb_imgpx_n;\n"; *(const char * *)tb_grow(v_lines) = tb_v5299; }
    { const char * tb_v5300 = "    tb_imgpx_n = need;\n"; *(const char * *)tb_grow(v_lines) = tb_v5300; }
    { const char * tb_v5301 = "    tb_img_dirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5301; }
    { const char * tb_v5302 = "    return tb_nimg++;\n"; *(const char * *)tb_grow(v_lines) = tb_v5302; }
    { const char * tb_v5303 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5303; }
    { const char * tb_v5304 = "// снимок кадра (что нарисовано сейчас) — новая картинка; потом draw_image рисует её за один раз\n"; *(const char * *)tb_grow(v_lines) = tb_v5304; }
    { const char * tb_v5305 = "TB_API long long tb_screen_image(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5305; }
    { const char * tb_v5306 = "    if (!tb_px) { tb_err = \"окно ещё не открыто\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5306; }
    { const char * tb_v5307 = "    size_t n = (size_t)tb_gw * tb_gh, need = tb_imgpx_n + n;\n"; *(const char * *)tb_grow(v_lines) = tb_v5307; }
    { const char * tb_v5308 = "    uint32_t *all = realloc(tb_imgpx, need * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v5308; }
    { const char * tb_v5309 = "    if (all) tb_imgpx = all;\n"; *(const char * *)tb_grow(v_lines) = tb_v5309; }
    { const char * tb_v5310 = "    tb_image *list = realloc(tb_imgs, (size_t)(tb_nimg + 1) * sizeof(tb_image));\n"; *(const char * *)tb_grow(v_lines) = tb_v5310; }
    { const char * tb_v5311 = "    if (list) tb_imgs = list;\n"; *(const char * *)tb_grow(v_lines) = tb_v5311; }
