    { const char * tb_v5380 = "static unsigned tb_ttf_glyph(const tb_font_t *f, unsigned u) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5380; }
    { const char * tb_v5381 = "    size_t c = f->cmap;\n"; *(const char * *)tb_grow(v_lines) = tb_v5381; }
