    { const char * tb_v5423 = "    p[0] = (float)x0; p[1] = (float)y0; p[2] = (float)x1; p[3] = (float)y1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5423; }
    { const char * tb_v5424 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5424; }
    { const char * tb_v5425 = "static void tb_quad(tb_edges *E, double x0, double y0, double cx, double cy, double x1, double y1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5425; }
    { const char * tb_v5426 = "    double dx = x0 - 2 * cx + x1, dy = y0 - 2 * cy + y1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5426; }
    { const char * tb_v5427 = "    int n = 1 + (int)sqrt(sqrt(dx * dx + dy * dy) * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v5427; }
    { const char * tb_v5428 = "    if (n > 16) n = 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v5428; }
    { const char * tb_v5429 = "    double px = x0, py = y0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5429; }
    { const char * tb_v5430 = "    for (int i = 1; i <= n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5430; }
