    { const char * tb_v5433 = "        tb_edge(E, px, py, qx, qy);\n"; *(const char * *)tb_grow(v_lines) = tb_v5433; }
    { const char * tb_v5434 = "        px = qx; py = qy;\n"; *(const char * *)tb_grow(v_lines) = tb_v5434; }
    { const char * tb_v5435 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5435; }
    { const char * tb_v5436 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5436; }
    { const char * tb_v5437 = "static void tb_ttf_outline(const tb_font_t *f, unsigned g, const double *m, tb_edges *E, int depth) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5437; }
    { const char * tb_v5438 = "    size_t len, o = tb_ttf_gpos(f, g, &len);\n"; *(const char * *)tb_grow(v_lines) = tb_v5438; }
