    { const char * tb_v5451 = "            else if (fl & 0x40) { a = tb_s16(f, p) / 16384.0; dd = tb_s16(f, p + 2) / 16384.0; p += 4; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5451; }
