    { const char * tb_v5755 = "                tb_gpu_frames, bad, first % tb_gw, first / tb_gw, tb_gpu_back[first] & 0xFFFFFF, tb_px[first] & 0xFFFFFF);\n"; *(const char * *)tb_grow(v_lines) = tb_v5755; }
    { const char * tb_v5756 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5756; }
