    { const char * tb_v8370 = "    if (tb_gpu_want()) tb_gpu_on = tb_vk_init(\"VK_KHR_xlib_surface\", tb_x_surface);\n"; *(const char * *)tb_grow(v_lines) = tb_v8370; }
