    { const char * tb_v8375 = "// знак клавиши → буква Unicode (русская раскладка в X11 — свои старые номера 0x6c0..0x6ff)\n"; *(const char * *)tb_grow(v_lines) = tb_v8375; }
    { const char * tb_v8376 = "TB_API unsigned tb_x_uni(KeySym s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8376; }
    { const char * tb_v8377 = "    static const unsigned short cyr[64] = { 0x44e, 0x430, 0x431, 0x446, 0x434, 0x435, 0x444, 0x433, 0x445, 0x438, 0x439, 0x43a, 0x43b, 0x43c, 0x43d, 0x43e, 0x43f, 0x44f, 0x440, 0x441, 0x442, 0x443, 0x436, 0x432, 0x44c, 0x44b, 0x437, 0x448, 0x44d, 0x449, 0x447, 0x44a, 0x42e, 0x410, 0x411, 0x426, 0x414, 0x415, 0x424, 0x413, 0x425, 0x418, 0x419, 0x41a, 0x41b, 0x41c, 0x41d, 0x41e, 0x41f, 0x42f, 0x420, 0x421, 0x422, 0x423, 0x416, 0x412, 0x42c, 0x42b, 0x417, 0x428, 0x42d, 0x429, 0x427, 0x42a };\n"; *(const char * *)tb_grow(v_lines) = tb_v8377; }
    { const char * tb_v8378 = "    if ((s >= 0x20 && s <= 0x7e) || (s >= 0xa0 && s <= 0xff)) return (unsigned)s;\n"; *(const char * *)tb_grow(v_lines) = tb_v8378; }
    { const char * tb_v8379 = "    if ((s & 0xff000000) == 0x01000000) return (unsigned)(s & 0xffffff);\n"; *(const char * *)tb_grow(v_lines) = tb_v8379; }
    { const char * tb_v8380 = "    if (s >= 0x6c0 && s <= 0x6ff) return cyr[s - 0x6c0];\n"; *(const char * *)tb_grow(v_lines) = tb_v8380; }
    { const char * tb_v8381 = "    if (s == 0x6a3) return 0x451;\n"; *(const char * *)tb_grow(v_lines) = tb_v8381; }
    { const char * tb_v8382 = "    if (s == 0x6b3) return 0x401;\n"; *(const char * *)tb_grow(v_lines) = tb_v8382; }
    { const char * tb_v8383 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8383; }
    { const char * tb_v8384 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8384; }
    { const char * tb_v8385 = "TB_API int tb_x_key(KeySym s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8385; }
    { const char * tb_v8386 = "    if (s >= XK_a && s <= XK_z) return 'A' + (int)(s - XK_a);\n"; *(const char * *)tb_grow(v_lines) = tb_v8386; }
    { const char * tb_v8387 = "    if (s >= XK_A && s <= XK_Z) return 'A' + (int)(s - XK_A);\n"; *(const char * *)tb_grow(v_lines) = tb_v8387; }
    { const char * tb_v8388 = "    if (s >= XK_0 && s <= XK_9) return '0' + (int)(s - XK_0);\n"; *(const char * *)tb_grow(v_lines) = tb_v8388; }
    { const char * tb_v8389 = "    switch (s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8389; }
    { const char * tb_v8390 = "    case XK_Return: return TB_K_ENTER; case XK_Escape: return TB_K_ESC; case XK_space: return TB_K_SPACE;\n"; *(const char * *)tb_grow(v_lines) = tb_v8390; }
    { const char * tb_v8391 = "    case XK_BackSpace: return TB_K_BACK; case XK_Tab: return TB_K_TAB; case XK_Up: return TB_K_UP;\n"; *(const char * *)tb_grow(v_lines) = tb_v8391; }
    { const char * tb_v8392 = "    case XK_Down: return TB_K_DOWN; case XK_Left: return TB_K_LEFT; case XK_Right: return TB_K_RIGHT;\n"; *(const char * *)tb_grow(v_lines) = tb_v8392; }
    { const char * tb_v8393 = "    case XK_Shift_L: case XK_Shift_R: return TB_K_SHIFT;\n"; *(const char * *)tb_grow(v_lines) = tb_v8393; }
    { const char * tb_v8394 = "    case XK_Control_L: case XK_Control_R: return TB_K_CTRL;\n"; *(const char * *)tb_grow(v_lines) = tb_v8394; }
    { const char * tb_v8395 = "    case XK_Alt_L: case XK_Alt_R: return TB_K_ALT;\n"; *(const char * *)tb_grow(v_lines) = tb_v8395; }
    { const char * tb_v8396 = "    case XK_Delete: return TB_K_DEL; case XK_Home: return TB_K_HOME; case XK_End: return TB_K_END;\n"; *(const char * *)tb_grow(v_lines) = tb_v8396; }
    { const char * tb_v8397 = "    case XK_Prior: return TB_K_PGUP; case XK_Next: return TB_K_PGDN;\n"; *(const char * *)tb_grow(v_lines) = tb_v8397; }
    { const char * tb_v8398 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8398; }
    { const char * tb_v8399 = "    if (s >= XK_F1 && s <= XK_F12) return TB_K_F1 + (int)(s - XK_F1);\n"; *(const char * *)tb_grow(v_lines) = tb_v8399; }
    { const char * tb_v8400 = "    if (s > 0x20 && s < 0x7f) return (int)s;   // знаки [ ] . , / - = : у X11 номер знака — это его код\n"; *(const char * *)tb_grow(v_lines) = tb_v8400; }
    { const char * tb_v8401 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8401; }
    { const char * tb_v8402 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8402; }
    { const char * tb_v8403 = "// буфер обмена X11: текст держит сама программа-владелец и отдаёт его по просьбе (SelectionRequest)\n"; *(const char * *)tb_grow(v_lines) = tb_v8403; }
    { const char * tb_v8404 = "TB_API char *tb_x_clip = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8404; }
    { const char * tb_v8405 = "TB_API void tb_x_clip_answer(XSelectionRequestEvent *r) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8405; }
    { const char * tb_v8406 = "    Atom utf8 = XInternAtom(tb_dpy, \"UTF8_STRING\", False), targets = XInternAtom(tb_dpy, \"TARGETS\", False);\n"; *(const char * *)tb_grow(v_lines) = tb_v8406; }
    { const char * tb_v8407 = "    XSelectionEvent ev;\n"; *(const char * *)tb_grow(v_lines) = tb_v8407; }
    { const char * tb_v8408 = "    memset(&ev, 0, sizeof ev);\n"; *(const char * *)tb_grow(v_lines) = tb_v8408; }
    { const char * tb_v8409 = "    ev.type = SelectionNotify; ev.display = r->display; ev.requestor = r->requestor;\n"; *(const char * *)tb_grow(v_lines) = tb_v8409; }
    { const char * tb_v8410 = "    ev.selection = r->selection; ev.target = r->target; ev.time = r->time; ev.property = None;\n"; *(const char * *)tb_grow(v_lines) = tb_v8410; }
    { const char * tb_v8411 = "    Atom prop = r->property ? r->property : r->target;\n"; *(const char * *)tb_grow(v_lines) = tb_v8411; }
    { const char * tb_v8412 = "    if (r->target == targets) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8412; }
    { const char * tb_v8413 = "        Atom list[3] = { targets, utf8, XA_STRING };\n"; *(const char * *)tb_grow(v_lines) = tb_v8413; }
    { const char * tb_v8414 = "        XChangeProperty(tb_dpy, r->requestor, prop, XA_ATOM, 32, PropModeReplace, (unsigned char *)list, 3);\n"; *(const char * *)tb_grow(v_lines) = tb_v8414; }
    { const char * tb_v8415 = "        ev.property = prop;\n"; *(const char * *)tb_grow(v_lines) = tb_v8415; }
    { const char * tb_v8416 = "    } else if ((r->target == utf8 || r->target == XA_STRING) && tb_x_clip) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8416; }
    { const char * tb_v8417 = "        XChangeProperty(tb_dpy, r->requestor, prop, r->target, 8, PropModeReplace, (unsigned char *)tb_x_clip, (int)strlen(tb_x_clip));\n"; *(const char * *)tb_grow(v_lines) = tb_v8417; }
    { const char * tb_v8418 = "        ev.property = prop;\n"; *(const char * *)tb_grow(v_lines) = tb_v8418; }
    { const char * tb_v8419 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8419; }
    { const char * tb_v8420 = "    XSendEvent(tb_dpy, r->requestor, False, 0, (XEvent *)&ev);\n"; *(const char * *)tb_grow(v_lines) = tb_v8420; }
    { const char * tb_v8421 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8421; }
    { const char * tb_v8422 = "TB_API void tb_gfx_clip_set(const char *s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8422; }
    { const char * tb_v8423 = "    free(tb_x_clip);\n"; *(const char * *)tb_grow(v_lines) = tb_v8423; }
    { const char * tb_v8424 = "    tb_x_clip = strdup(s);\n"; *(const char * *)tb_grow(v_lines) = tb_v8424; }
    { const char * tb_v8425 = "    if (!tb_dpy) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8425; }
    { const char * tb_v8426 = "    XSetSelectionOwner(tb_dpy, XInternAtom(tb_dpy, \"CLIPBOARD\", False), tb_xw, CurrentTime);\n"; *(const char * *)tb_grow(v_lines) = tb_v8426; }
    { const char * tb_v8427 = "    XFlush(tb_dpy);\n"; *(const char * *)tb_grow(v_lines) = tb_v8427; }
    { const char * tb_v8428 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8428; }
    { const char * tb_v8429 = "TB_API char *tb_gfx_clip_get(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8429; }
    { const char * tb_v8430 = "    if (!tb_dpy) return tb_x_clip ? strdup(tb_x_clip) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8430; }
    { const char * tb_v8431 = "    Atom clip = XInternAtom(tb_dpy, \"CLIPBOARD\", False), utf8 = XInternAtom(tb_dpy, \"UTF8_STRING\", False);\n"; *(const char * *)tb_grow(v_lines) = tb_v8431; }
    { const char * tb_v8432 = "    Window owner = XGetSelectionOwner(tb_dpy, clip);\n"; *(const char * *)tb_grow(v_lines) = tb_v8432; }
    { const char * tb_v8433 = "    if (owner == tb_xw) return tb_x_clip ? strdup(tb_x_clip) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8433; }
    { const char * tb_v8434 = "    if (owner == None) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8434; }
    { const char * tb_v8435 = "    Atom prop = XInternAtom(tb_dpy, \"TACHBIT_CLIP\", False);\n"; *(const char * *)tb_grow(v_lines) = tb_v8435; }
    { const char * tb_v8436 = "    XConvertSelection(tb_dpy, clip, utf8, prop, tb_xw, CurrentTime);\n"; *(const char * *)tb_grow(v_lines) = tb_v8436; }
    { const char * tb_v8437 = "    XFlush(tb_dpy);\n"; *(const char * *)tb_grow(v_lines) = tb_v8437; }
    { const char * tb_v8438 = "    // ждём ответ владельца не дольше полсекунды; чужие события по дороге не теряем\n"; *(const char * *)tb_grow(v_lines) = tb_v8438; }
    { const char * tb_v8439 = "    long long until = tb_time_ms() + 500;\n"; *(const char * *)tb_grow(v_lines) = tb_v8439; }
    { const char * tb_v8440 = "    while (tb_time_ms() < until) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8440; }
    { const char * tb_v8441 = "        XEvent e;\n"; *(const char * *)tb_grow(v_lines) = tb_v8441; }
    { const char * tb_v8442 = "        if (XCheckTypedWindowEvent(tb_dpy, tb_xw, SelectionNotify, &e)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8442; }
    { const char * tb_v8443 = "            if (e.xselection.property == None) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8443; }
    { const char * tb_v8444 = "            Atom type; int fmt; unsigned long n = 0, rest = 0; unsigned char *data = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8444; }
    { const char * tb_v8445 = "            XGetWindowProperty(tb_dpy, tb_xw, prop, 0, 1 << 24, True, AnyPropertyType, &type, &fmt, &n, &rest, &data);\n"; *(const char * *)tb_grow(v_lines) = tb_v8445; }
    { const char * tb_v8446 = "            char *out = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8446; }
    { const char * tb_v8447 = "            if (data && fmt == 8) { out = malloc(n + 1); if (out) { memcpy(out, data, n); out[n] = 0; } }\n"; *(const char * *)tb_grow(v_lines) = tb_v8447; }
    { const char * tb_v8448 = "            if (data) XFree(data);\n"; *(const char * *)tb_grow(v_lines) = tb_v8448; }
    { const char * tb_v8449 = "            return out;\n"; *(const char * *)tb_grow(v_lines) = tb_v8449; }
    { const char * tb_v8450 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v8450; }
    { const char * tb_v8451 = "        if (XCheckTypedEvent(tb_dpy, SelectionRequest, &e)) tb_x_clip_answer(&e.xselectionrequest);\n"; *(const char * *)tb_grow(v_lines) = tb_v8451; }
    { const char * tb_v8452 = "        struct timespec ts = { 0, 2000000 };\n"; *(const char * *)tb_grow(v_lines) = tb_v8452; }
    { const char * tb_v8453 = "        nanosleep(&ts, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v8453; }
    { const char * tb_v8454 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8454; }
    { const char * tb_v8455 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8455; }
    { const char * tb_v8456 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8456; }
