    { const char * tb_v8500 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v8500; }
    { const char * tb_v8501 = "// TB_GPU_CHECK: проба смешивания. Видеокарты считают смешивание по-своему (AMD на Mac — с малой\n"; *(const char * *)tb_grow(v_lines) = tb_v8501; }
    { const char * tb_v8502 = "// точностью, ошибка зависит и от цвета буквы, и от фона), поэтому проба берёт все сочетания:\n"; *(const char * *)tb_grow(v_lines) = tb_v8502; }
    { const char * tb_v8503 = "// цвет c, фон d, прозрачность a — 256 × 256 × 256 точек, кадр за кадром, и процессор дальше\n"; *(const char * *)tb_grow(v_lines) = tb_v8503; }
    { const char * tb_v8504 = "// смешивает по этой таблице (tb_blend_lut[c][d][a]). Делается один раз, когда есть и окно, и шрифт.\n"; *(const char * *)tb_grow(v_lines) = tb_v8504; }
    { const char * tb_v8505 = "// После пробы кадр видеокарты снова становится таким же, как у процессора (копия tb_px)\n"; *(const char * *)tb_grow(v_lines) = tb_v8505; }
    { const char * tb_v8506 = "TB_API void tb_gpu_blend_probe(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8506; }
    { const char * tb_v8507 = "    if (!tb_gpu_on || !tb_gpu_check || tb_blend_cal || !tb_px || !tb_nfonts) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8507; }
    { const char * tb_v8508 = "    uint8_t *lut = malloc((size_t)1 << 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v8508; }
    { const char * tb_v8509 = "    if (!lut) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8509; }
    { const char * tb_v8510 = "    size_t n = (size_t)tb_gw * tb_gh, p0 = tb_imgpx_n, need = p0 + 3 * n;\n"; *(const char * *)tb_grow(v_lines) = tb_v8510; }
    { const char * tb_v8511 = "    int n0 = tb_nimg;\n"; *(const char * *)tb_grow(v_lines) = tb_v8511; }
    { const char * tb_v8512 = "    uint32_t *all = need <= 0xFFFFFFFFu ? realloc(tb_imgpx, need * 4) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8512; }
    { const char * tb_v8513 = "    tb_image *list = realloc(tb_imgs, (size_t)(n0 + 3) * sizeof(tb_image));\n"; *(const char * *)tb_grow(v_lines) = tb_v8513; }
    { const char * tb_v8514 = "    if (all) tb_imgpx = all;\n"; *(const char * *)tb_grow(v_lines) = tb_v8514; }
    { const char * tb_v8515 = "    if (list) tb_imgs = list;\n"; *(const char * *)tb_grow(v_lines) = tb_v8515; }
    { const char * tb_v8516 = "    if (!all || !list) { free(lut); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8516; }
    { const char * tb_v8517 = "    for (int k = 0; k < 3; k++) { tb_imgs[n0 + k].w = tb_gw; tb_imgs[n0 + k].h = tb_gh; tb_imgs[n0 + k].off = (uint32_t)(p0 + k * n); }\n"; *(const char * *)tb_grow(v_lines) = tb_v8517; }
    { const char * tb_v8518 = "    tb_nimg = n0 + 3; tb_imgpx_n = need;\n"; *(const char * *)tb_grow(v_lines) = tb_v8518; }
    { const char * tb_v8519 = "    uint32_t *keep = tb_imgpx + p0 + 2 * n;   // кадр процессора: вернуть его видеокарте после пробы\n"; *(const char * *)tb_grow(v_lines) = tb_v8519; }
    { const char * tb_v8520 = "    for (size_t q = 0; q < n; q++) keep[q] = 0xFF000000u | tb_px[q];\n"; *(const char * *)tb_grow(v_lines) = tb_v8520; }
    { const char * tb_v8521 = "    tb_gpu_probing = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8521; }
    { const char * tb_v8522 = "    int ok = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8522; }
    { const char * tb_v8523 = "    for (size_t from = 0; from < ((size_t)1 << 24) && ok; from += n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8523; }
    { const char * tb_v8524 = "        uint32_t *bg = tb_imgpx + p0, *fg = bg + n;\n"; *(const char * *)tb_grow(v_lines) = tb_v8524; }
    { const char * tb_v8525 = "        for (size_t q = 0; q < n; q++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8525; }
    { const char * tb_v8526 = "            size_t i = (from + q) & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v8526; }
    { const char * tb_v8527 = "            uint32_t c = (uint32_t)(i >> 16), d = (uint32_t)(i >> 8) & 255, a = (uint32_t)i & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v8527; }
    { const char * tb_v8528 = "            bg[q] = 0xFF000000u | d * 0x010101u;\n"; *(const char * *)tb_grow(v_lines) = tb_v8528; }
    { const char * tb_v8529 = "            fg[q] = (a << 24) | c * 0x010101u;\n"; *(const char * *)tb_grow(v_lines) = tb_v8529; }
    { const char * tb_v8530 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v8530; }
    { const char * tb_v8531 = "        tb_img_dirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8531; }
    { const char * tb_v8532 = "        tb_gpu_image(n0, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v8532; }
    { const char * tb_v8533 = "        tb_gpu_image_a(n0 + 1, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v8533; }
    { const char * tb_v8534 = "        tb_gpu_flush(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v8534; }
    { const char * tb_v8535 = "        if (!tb_gpu_back) { ok = 0; break; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8535; }
    { const char * tb_v8536 = "        for (size_t q = 0; q < n && from + q < ((size_t)1 << 24); q++) lut[from + q] = (uint8_t)(tb_gpu_back[q] & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v8536; }
    { const char * tb_v8537 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8537; }
    { const char * tb_v8538 = "    tb_gpu_image(n0 + 2, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v8538; }
    { const char * tb_v8539 = "    tb_gpu_flush(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v8539; }
    { const char * tb_v8540 = "    tb_gpu_probing = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8540; }
    { const char * tb_v8541 = "    tb_nimg = n0; tb_imgpx_n = p0; tb_img_dirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8541; }
    { const char * tb_v8542 = "    if (!ok) { free(lut); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8542; }
    { const char * tb_v8543 = "    tb_blend_lut = lut;\n"; *(const char * *)tb_grow(v_lines) = tb_v8543; }
    { const char * tb_v8544 = "    tb_blend_cal = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8544; }
    { const char * tb_v8545 = "    const char *e = getenv(\"TB_GPU_INFO\");\n"; *(const char * *)tb_grow(v_lines) = tb_v8545; }
    { const char * tb_v8546 = "    if (e && e[0] == '1') {\n"; *(const char * *)tb_grow(v_lines) = tb_v8546; }
    { const char * tb_v8547 = "        long long diff = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8547; }
    { const char * tb_v8548 = "        for (size_t i = 0; i < ((size_t)1 << 24); i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8548; }
    { const char * tb_v8549 = "            uint32_t c = (uint32_t)(i >> 16), d = (uint32_t)(i >> 8) & 255, a = (uint32_t)i & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v8549; }
    { const char * tb_v8550 = "            uint32_t w = a == 0 ? d : (c * a + 127) / 255 + (d * (255 - a) + 127) / 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v8550; }
    { const char * tb_v8551 = "            diff += lut[i] != w;\n"; *(const char * *)tb_grow(v_lines) = tb_v8551; }
    { const char * tb_v8552 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v8552; }
    { const char * tb_v8553 = "        fprintf(stderr, \"TB_GPU_CHECK: смешивание на этой видеокарте не как округление к ближайшему: %lld из %d\\n\", diff, 1 << 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v8553; }
    { const char * tb_v8554 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8554; }
    { const char * tb_v8555 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8555; }
    { const char * tb_v8556 = "// window_sharp(): окно в настоящих точках экрана (Retina, 150% и 200% на Windows). Размер в window_open\n"; *(const char * *)tb_grow(v_lines) = tb_v8556; }
    { const char * tb_v8557 = "// остаётся в «обычных» точках, а кадр, window_w/h и мышь — в настоящих; window_scale() — во сколько раз\n"; *(const char * *)tb_grow(v_lines) = tb_v8557; }
    { const char * tb_v8558 = "TB_API double tb_gfx_scale(void);   // своя у каждой системы\n"; *(const char * *)tb_grow(v_lines) = tb_v8558; }
    { const char * tb_v8559 = "TB_API void tb_window_sharp(void) { if (!tb_px) tb_sharp = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8559; }
    { const char * tb_v8560 = "TB_API double tb_window_scale(void) { return tb_sc; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8560; }
    { const char * tb_v8561 = "TB_API void tb_window_open(long long w, long long h, const char *title) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8561; }
    { const char * tb_v8562 = "    if (tb_px) { tb_err = \"окно уже открыто\"; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8562; }
    { const char * tb_v8563 = "    if (w < 1 || h < 1 || w > 8192 || h > 8192) { tb_err = \"размер окна от 1 до 8192\"; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8563; }
    { const char * tb_v8564 = "    if (tb_sharp) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8564; }
    { const char * tb_v8565 = "        tb_sc = tb_gfx_scale();\n"; *(const char * *)tb_grow(v_lines) = tb_v8565; }
    { const char * tb_v8566 = "        if (tb_sc < 1) tb_sc = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8566; }
    { const char * tb_v8567 = "        if (tb_sc > 4) tb_sc = 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v8567; }
    { const char * tb_v8568 = "        w = (long long)(w * tb_sc + 0.5); h = (long long)(h * tb_sc + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v8568; }
    { const char * tb_v8569 = "        if (w > 8192) w = 8192;\n"; *(const char * *)tb_grow(v_lines) = tb_v8569; }
    { const char * tb_v8570 = "        if (h > 8192) h = 8192;\n"; *(const char * *)tb_grow(v_lines) = tb_v8570; }
    { const char * tb_v8571 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8571; }
    { const char * tb_v8572 = "    tb_gw = (int)w; tb_gh = (int)h;\n"; *(const char * *)tb_grow(v_lines) = tb_v8572; }
    { const char * tb_v8573 = "    tb_px = calloc((size_t)tb_gw * tb_gh, 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v8573; }
    { const char * tb_v8574 = "    if (!tb_gfx_open(title)) { free(tb_px); tb_px = 0; tb_err = \"не могу открыть окно: нет экрана\"; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8574; }
    { const char * tb_v8575 = "    if (tb_gpu_on && tb_gpu_check) { atexit(tb_gpu_report); tb_gpu_blend_probe(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v8575; }
    { const char * tb_v8576 = "    tb_last_frame = tb_time_ms();\n"; *(const char * *)tb_grow(v_lines) = tb_v8576; }
    { const char * tb_v8577 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8577; }
    { const char * tb_v8578 = "// показать кадр, принять клавиши и мышь, держать 60 кадров в секунду; false — окно закрыли\n"; *(const char * *)tb_grow(v_lines) = tb_v8578; }
    { const char * tb_v8579 = "// окно поменяло размер: новый кадр, старое остаётся в левом верхнем углу, новое место — чёрное\n"; *(const char * *)tb_grow(v_lines) = tb_v8579; }
    { const char * tb_v8580 = "TB_API void tb_apply_resize(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8580; }
    { const char * tb_v8581 = "    if (!tb_new_w) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8581; }
    { const char * tb_v8582 = "    int nw = tb_new_w > 8192 ? 8192 : tb_new_w, nh = tb_new_h > 8192 ? 8192 : tb_new_h, ow = tb_gw, oh = tb_gh;\n"; *(const char * *)tb_grow(v_lines) = tb_v8582; }
    { const char * tb_v8583 = "    tb_new_w = tb_new_h = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8583; }
    { const char * tb_v8584 = "    if (nw < 1 || nh < 1 || (nw == ow && nh == oh)) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8584; }
    { const char * tb_v8585 = "    uint32_t *np = calloc((size_t)nw * nh, 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v8585; }
    { const char * tb_v8586 = "    if (!np) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8586; }
    { const char * tb_v8587 = "    for (int y = 0; y < oh && y < nh; y++) memcpy(np + (size_t)y * nw, tb_px + (size_t)y * ow, (size_t)(ow < nw ? ow : nw) * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v8587; }
    { const char * tb_v8588 = "    free(tb_px);\n"; *(const char * *)tb_grow(v_lines) = tb_v8588; }
    { const char * tb_v8589 = "    tb_px = np; tb_gw = nw; tb_gh = nh;\n"; *(const char * *)tb_grow(v_lines) = tb_v8589; }
    { const char * tb_v8590 = "    tb_gfx_reimage();\n"; *(const char * *)tb_grow(v_lines) = tb_v8590; }
    { const char * tb_v8591 = "    if (tb_gpu_on && !tb_gpu_resize(ow, oh)) fprintf(stderr, \"видеокарта: не получилось поменять размер кадра\\n\");\n"; *(const char * *)tb_grow(v_lines) = tb_v8591; }
    { const char * tb_v8592 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8592; }
    { const char * tb_v8593 = "TB_API long long tb_window_w(void) { if (tb_px && !tb_resizable) { tb_resizable = 1; tb_gfx_resizable(); } return tb_gw; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8593; }
    { const char * tb_v8594 = "TB_API long long tb_window_h(void) { if (tb_px && !tb_resizable) { tb_resizable = 1; tb_gfx_resizable(); } return tb_gh; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8594; }
    { const char * tb_v8595 = "// частота кадров: -1 — как у экрана (по умолчанию), 0 — сколько успеет, n — n кадров в секунду (set_fps)\n"; *(const char * *)tb_grow(v_lines) = tb_v8595; }
