    { const char * tb_v8605 = "TB_API long long tb_fps(void) { return tb_fps_v ? tb_fps_v : tb_frame_ms_v > 0 ? (long long)(1000 / tb_frame_ms_v) : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8605; }
    { const char * tb_v8606 = "// показать кадр, принять клавиши и мышь, держать частоту кадров; false — окно закрыли\n"; *(const char * *)tb_grow(v_lines) = tb_v8606; }
    { const char * tb_v8607 = "TB_API int tb_window_alive(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8607; }
    { const char * tb_v8608 = "    if (!tb_px || tb_gclosed) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8608; }
    { const char * tb_v8609 = "    tb_gfx_events();   // здесь показывается прошлый кадр\n"; *(const char * *)tb_grow(v_lines) = tb_v8609; }
    { const char * tb_v8610 = "    tb_zclr = tb_gzclr = 1;   // новый кадр: глубина 3D начинается заново\n"; *(const char * *)tb_grow(v_lines) = tb_v8610; }
    { const char * tb_v8611 = "    tb_apply_resize();\n"; *(const char * *)tb_grow(v_lines) = tb_v8611; }
    { const char * tb_v8612 = "    // TB_FPS_FREE=1 — без ограничения (для замеров скорости), как set_fps(0)\n"; *(const char * *)tb_grow(v_lines) = tb_v8612; }
    { const char * tb_v8613 = "    static int free_fps = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8613; }
    { const char * tb_v8614 = "    if (free_fps < 0) free_fps = getenv(\"TB_FPS_FREE\") != 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8614; }
    { const char * tb_v8615 = "    long long now = tb_time_us(), period = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8615; }
    { const char * tb_v8616 = "    if (!tb_last_us) tb_last_us = now;\n"; *(const char * *)tb_grow(v_lines) = tb_v8616; }
    { const char * tb_v8617 = "    if (free_fps || tb_fps_want == 0) period = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8617; }
    { const char * tb_v8618 = "    else if (tb_fps_want > 0) period = 1000000 / tb_fps_want;\n"; *(const char * *)tb_grow(v_lines) = tb_v8618; }
    { const char * tb_v8619 = "    // как у экрана: видеокарта сама ждёт обновления экрана (60 Гц — 60 кадров, 120 Гц — 120);\n"; *(const char * *)tb_grow(v_lines) = tb_v8619; }
    { const char * tb_v8620 = "    // кадр пришёл быстрее 4 мс — экран частоту не держит, держим сами 60 кадров в секунду\n"; *(const char * *)tb_grow(v_lines) = tb_v8620; }
    { const char * tb_v8621 = "    else if (!tb_gpu_on || now - tb_last_us < 4000) period = 16667;\n"; *(const char * *)tb_grow(v_lines) = tb_v8621; }
    { const char * tb_v8622 = "    if (period && now - tb_last_us < period) { usleep((useconds_t)(period - (now - tb_last_us))); now = tb_time_us(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v8622; }
