    { const char * tb_v8640 = "    if (TB_CPU_DRAW) for (long long i = 0; i < (long long)tb_gw * tb_gh; i++) tb_px[i] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v8640; }
    { const char * tb_v8641 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8641; }
