    { const char * tb_v8666 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8666; }
    { const char * tb_v8667 = "// точка с покрытием cov (0..1): цвет c (может быть rgba) смешивается с тем, что под ним\n"; *(const char * *)tb_grow(v_lines) = tb_v8667; }
    { const char * tb_v8668 = "TB_INL void tb_cover(long long x, long long y, uint32_t c, double cov) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8668; }
    { const char * tb_v8669 = "    if (x < 0 || y < 0 || x >= tb_gw || y >= tb_gh || cov <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8669; }
    { const char * tb_v8670 = "    uint32_t a = 255 - ((c >> 24) & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v8670; }
    { const char * tb_v8671 = "    a = (uint32_t)(a * (cov > 1 ? 1 : cov) + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v8671; }
    { const char * tb_v8672 = "    if (a == 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8672; }
    { const char * tb_v8673 = "    uint32_t *p = &tb_px[y * tb_gw + x];\n"; *(const char * *)tb_grow(v_lines) = tb_v8673; }
    { const char * tb_v8674 = "    *p = a >= 255 ? (c & 0xFFFFFF) : tb_mix(*p, ((255 - a) << 24) | (c & 0xFFFFFF));\n"; *(const char * *)tb_grow(v_lines) = tb_v8674; }
    { const char * tb_v8675 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8675; }
    { const char * tb_v8676 = "// draw_shadow(x, y, w, h, r, size, c): мягкая тень скруглённого прямоугольника — внутри цвет c,\n"; *(const char * *)tb_grow(v_lines) = tb_v8676; }
    { const char * tb_v8677 = "// снаружи к size точкам сходит на нет. Корень считается только у кольца и углов, середина — простое смешивание.\n"; *(const char * *)tb_grow(v_lines) = tb_v8677; }
    { const char * tb_v8678 = "TB_API void tb_draw_shadow(long long x, long long y, long long w, long long h, long long r, long long size, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8678; }
    { const char * tb_v8679 = "    if (!tb_px || w <= 0 || h <= 0 || size <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8679; }
    { const char * tb_v8680 = "    if (r * 2 > w) r = w / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v8680; }
    { const char * tb_v8681 = "    if (r * 2 > h) r = h / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v8681; }
    { const char * tb_v8682 = "    if (tb_gpu_on) {                                   // видеокарта: слоями (без сглаживания)\n"; *(const char * *)tb_grow(v_lines) = tb_v8682; }
    { const char * tb_v8683 = "        for (long long k = size; k > 0; k -= 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8683; }
    { const char * tb_v8684 = "            double f = 1.0 - (double)k / size;\n"; *(const char * *)tb_grow(v_lines) = tb_v8684; }
    { const char * tb_v8685 = "            long long a = (long long)((255 - ((c >> 24) & 255)) * f * f / (size / 2.0) + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v8685; }
    { const char * tb_v8686 = "            if (a > 0) tb_gpu_rect(x - k, y - k + r, w + 2 * k, h + 2 * k - 2 * r, ((255 - a) << 24) | (c & 0xFFFFFF));\n"; *(const char * *)tb_grow(v_lines) = tb_v8686; }
    { const char * tb_v8687 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v8687; }
    { const char * tb_v8688 = "        if (!TB_CPU_DRAW) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8688; }
    { const char * tb_v8689 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8689; }
    { const char * tb_v8690 = "    double hw = w / 2.0, hh = h / 2.0, cx = x + hw, cy = y + hh;\n"; *(const char * *)tb_grow(v_lines) = tb_v8690; }
    { const char * tb_v8691 = "    long long y0 = y - size < 0 ? 0 : y - size, y1 = y + h + size > tb_gh ? tb_gh : y + h + size;\n"; *(const char * *)tb_grow(v_lines) = tb_v8691; }
    { const char * tb_v8692 = "    for (long long j = y0; j < y1; j++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8692; }
    { const char * tb_v8693 = "        double py = j + 0.5, dy = fabs(py - cy) - (hh - r);\n"; *(const char * *)tb_grow(v_lines) = tb_v8693; }
    { const char * tb_v8694 = "        if (dy < 0) dy = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8694; }
    { const char * tb_v8695 = "        long long xa = x - size < 0 ? 0 : x - size, xb = x + w + size > tb_gw ? tb_gw : x + w + size;\n"; *(const char * *)tb_grow(v_lines) = tb_v8695; }
    { const char * tb_v8696 = "        for (long long i = xa; i < xb; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8696; }
    { const char * tb_v8697 = "            double px = i + 0.5, dx = fabs(px - cx) - (hw - r);\n"; *(const char * *)tb_grow(v_lines) = tb_v8697; }
    { const char * tb_v8698 = "            if (dx < 0) dx = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8698; }
    { const char * tb_v8699 = "            if (dx == 0 && dy == 0) { tb_px[j * tb_gw + i] = tb_mix(tb_px[j * tb_gw + i], (uint32_t)c); continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8699; }
    { const char * tb_v8700 = "            double d = sqrt(dx * dx + dy * dy) - r;\n"; *(const char * *)tb_grow(v_lines) = tb_v8700; }
    { const char * tb_v8701 = "            if (d >= size) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v8701; }
    { const char * tb_v8702 = "            double f = d <= 0 ? 1 : 1 - d / size;\n"; *(const char * *)tb_grow(v_lines) = tb_v8702; }
    { const char * tb_v8703 = "            tb_cover(i, j, (uint32_t)c, f * f);\n"; *(const char * *)tb_grow(v_lines) = tb_v8703; }
    { const char * tb_v8704 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v8704; }
    { const char * tb_v8705 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8705; }
    { const char * tb_v8706 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8706; }
    { const char * tb_v8707 = "// скругление углов: \"\" или \"all\" — все; иначе слова top bottom left right tl tr bl br через пробел\n"; *(const char * *)tb_grow(v_lines) = tb_v8707; }
    { const char * tb_v8708 = "TB_API int tb_corners(const char *s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8708; }
    { const char * tb_v8709 = "    if (!s || !*s) return 15;\n"; *(const char * *)tb_grow(v_lines) = tb_v8709; }
    { const char * tb_v8710 = "    int m = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8710; }
    { const char * tb_v8711 = "    const char *w[] = { \"all\", \"top\", \"bottom\", \"left\", \"right\", \"tl\", \"tr\", \"bl\", \"br\" };\n"; *(const char * *)tb_grow(v_lines) = tb_v8711; }
    { const char * tb_v8712 = "    const int v[] = { 15, 3, 12, 5, 10, 1, 2, 4, 8 };\n"; *(const char * *)tb_grow(v_lines) = tb_v8712; }
    { const char * tb_v8713 = "    while (*s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8713; }
    { const char * tb_v8714 = "        while (*s == ' ' || *s == ',') s++;\n"; *(const char * *)tb_grow(v_lines) = tb_v8714; }
    { const char * tb_v8715 = "        const char *e = s;\n"; *(const char * *)tb_grow(v_lines) = tb_v8715; }
    { const char * tb_v8716 = "        while (*e && *e != ' ' && *e != ',') e++;\n"; *(const char * *)tb_grow(v_lines) = tb_v8716; }
    { const char * tb_v8717 = "        for (int i = 0; i < 9; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v8717; }
    { const char * tb_v8718 = "            if ((size_t)(e - s) == strlen(w[i]) && strncmp(s, w[i], (size_t)(e - s)) == 0) m |= v[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v8718; }
    { const char * tb_v8719 = "        s = e;\n"; *(const char * *)tb_grow(v_lines) = tb_v8719; }
    { const char * tb_v8720 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8720; }
    { const char * tb_v8721 = "    return m;\n"; *(const char * *)tb_grow(v_lines) = tb_v8721; }
    { const char * tb_v8722 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8722; }
    { const char * tb_v8723 = "// прямоугольник со скруглёнными углами, края сглажены; цвет может быть полупрозрачным (rgba)\n"; *(const char * *)tb_grow(v_lines) = tb_v8723; }
    { const char * tb_v8724 = "TB_API void tb_draw_round(long long x, long long y, long long w, long long h, long long r, const char *corners, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8724; }
    { const char * tb_v8725 = "    if (!tb_px || w <= 0 || h <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8725; }
