    { const char * tb_v8762 = "// размыть то, что уже нарисовано в прямоугольнике (матовое стекло, мягкий фон): три прохода «ящиком»\n"; *(const char * *)tb_grow(v_lines) = tb_v8762; }
    { const char * tb_v8763 = "// размытие одного ряда (n точек с шагом step в буфере b) скользящей суммой окна 2r+1; tmp — n точек\n"; *(const char * *)tb_grow(v_lines) = tb_v8763; }
    { const char * tb_v8764 = "TB_INL void tb_blur_run(uint32_t *b, long long n, long long step, long long r, uint32_t *tmp) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8764; }
    { const char * tb_v8765 = "    for (long long k = 0; k < n; k++) tmp[k] = b[k * step];\n"; *(const char * *)tb_grow(v_lines) = tb_v8765; }
    { const char * tb_v8766 = "    long long win = 2 * r + 1, sr = 0, sg = 0, sb = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8766; }
    { const char * tb_v8767 = "    uint64_t mul = (uint64_t)(((1u << 24) + win / 2) / win);   // деление — умножением (оно в десятки раз быстрее)\n"; *(const char * *)tb_grow(v_lines) = tb_v8767; }
    { const char * tb_v8768 = "    for (long long k = -r; k <= r; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8768; }
    { const char * tb_v8769 = "        uint32_t v = tmp[k < 0 ? 0 : k >= n ? n - 1 : k];\n"; *(const char * *)tb_grow(v_lines) = tb_v8769; }
