    { const char * tb_v8778 = "        sb += (long long)(in & 255) - (out & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v8778; }
    { const char * tb_v8779 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8779; }
    { const char * tb_v8780 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8780; }
    { const char * tb_v8781 = "// матовое стекло: размытие прямоугольника кадра. Большое размытие (r >= 4) считается на картинке\n"; *(const char * *)tb_grow(v_lines) = tb_v8781; }
    { const char * tb_v8782 = "// вдвое меньше (в 4 раза меньше точек), потом плавно растягивается обратно — на глаз то же самое.\n"; *(const char * *)tb_grow(v_lines) = tb_v8782; }
    { const char * tb_v8783 = "TB_API void tb_blur_rect(long long x, long long y, long long w, long long h, long long r) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8783; }
    { const char * tb_v8784 = "    if (!tb_px || r <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8784; }
    { const char * tb_v8785 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y, x1 = x + w > tb_gw ? tb_gw : x + w, y1 = y + h > tb_gh ? tb_gh : y + h;\n"; *(const char * *)tb_grow(v_lines) = tb_v8785; }
