    { const char * tb_v8841 = "TB_API void tb_draw_line(long long x0, long long y0, long long x1, long long y1, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8841; }
    { const char * tb_v8842 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8842; }
