    { const char * tb_v8853 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8853; }
    { const char * tb_v8854 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8854; }
    { const char * tb_v8855 = "// Треугольник. Правило точек одно для процессора и видеокарты (кадры совпадают точка в точку):\n"; *(const char * *)tb_grow(v_lines) = tb_v8855; }
    { const char * tb_v8856 = "// точка (x, y) берётся по своему центру (x + 0.5, y + 0.5); углы обходятся так, что площадь > 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8856; }
    { const char * tb_v8857 = "// для каждой стороны a→b: e = (bx-ax)*(2y+1-2ay) - (by-ay)*(2x+1-2ax); точка внутри, если e > 0\n"; *(const char * *)tb_grow(v_lines) = tb_v8857; }
    { const char * tb_v8858 = "// для всех трёх, а если e == 0 — только на сторонах с by > ay или (by == ay и bx < ax).\n"; *(const char * *)tb_grow(v_lines) = tb_v8858; }
    { const char * tb_v8859 = "// Так у двух соседних треугольников общая сторона рисуется ровно один раз.\n"; *(const char * *)tb_grow(v_lines) = tb_v8859; }
    { const char * tb_v8860 = "// Углы дальше ±8192 точек: треугольник сначала обрезается рамкой вокруг окна (tb_poly_draw) —\n"; *(const char * *)tb_grow(v_lines) = tb_v8860; }
    { const char * tb_v8861 = "// тогда в шейдере (32-битные числа) ничего не переполняется.\n"; *(const char * *)tb_grow(v_lines) = tb_v8861; }
    { const char * tb_v8862 = "TB_INL long long tb_tri_clamp(long long v) { return v < -8192 ? -8192 : v > 8192 ? 8192 : v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8862; }
    { const char * tb_v8863 = "// t = x1 y1 x2 y2 x3 y3; 0 — рисовать нечего (площадь 0 или целиком вне окна)\n"; *(const char * *)tb_grow(v_lines) = tb_v8863; }
    { const char * tb_v8864 = "TB_INL int tb_tri_prep(long long *t) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8864; }
    { const char * tb_v8865 = "    for (int i = 0; i < 6; i++) t[i] = tb_tri_clamp(t[i]);\n"; *(const char * *)tb_grow(v_lines) = tb_v8865; }
    { const char * tb_v8866 = "    long long a2 = (t[2] - t[0]) * (t[5] - t[1]) - (t[3] - t[1]) * (t[4] - t[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v8866; }
    { const char * tb_v8867 = "    if (a2 == 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8867; }
    { const char * tb_v8868 = "    if (a2 < 0) { long long x = t[2], y = t[3]; t[2] = t[4]; t[3] = t[5]; t[4] = x; t[5] = y; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8868; }
    { const char * tb_v8869 = "    long long x0 = t[0], x1 = t[0], y0 = t[1], y1 = t[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v8869; }
    { const char * tb_v8870 = "    for (int i = 2; i < 6; i += 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8870; }
    { const char * tb_v8871 = "        if (t[i] < x0) x0 = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v8871; }
    { const char * tb_v8872 = "        if (t[i] > x1) x1 = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v8872; }
    { const char * tb_v8873 = "        if (t[i + 1] < y0) y0 = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v8873; }
    { const char * tb_v8874 = "        if (t[i + 1] > y1) y1 = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v8874; }
    { const char * tb_v8875 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8875; }
    { const char * tb_v8876 = "    return !(x1 < 0 || y1 < 0 || x0 > tb_gw || y0 > tb_gh);\n"; *(const char * *)tb_grow(v_lines) = tb_v8876; }
    { const char * tb_v8877 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8877; }
    { const char * tb_v8878 = "TB_INL int tb_tri_edge(long long ax, long long ay, long long bx, long long by, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8878; }
    { const char * tb_v8879 = "    long long ex = bx - ax, ey = by - ay, e = ex * (2 * y + 1 - 2 * ay) - ey * (2 * x + 1 - 2 * ax);\n"; *(const char * *)tb_grow(v_lines) = tb_v8879; }
    { const char * tb_v8880 = "    return e > 0 || (e == 0 && (ey > 0 || (ey == 0 && ex < 0)));\n"; *(const char * *)tb_grow(v_lines) = tb_v8880; }
    { const char * tb_v8881 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8881; }
    { const char * tb_v8882 = "// глубина точки (x, y) по плоскости треугольника — так же, как в шейдере: 32-битные числа\n"; *(const char * *)tb_grow(v_lines) = tb_v8882; }
    { const char * tb_v8883 = "// без знака (переполнение по кругу), потом сдвиг; 0 — у самой камеры, 16777215 — далеко\n"; *(const char * *)tb_grow(v_lines) = tb_v8883; }
    { const char * tb_v8884 = "TB_INL uint32_t tb_tri3_depth(const uint32_t *pl, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8884; }
    { const char * tb_v8885 = "    uint32_t k = pl[2] + pl[0] * (uint32_t)(2 * x + 1) + pl[1] * (uint32_t)(2 * y + 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v8885; }
    { const char * tb_v8886 = "    int32_t d = (int32_t)k >> 6;\n"; *(const char * *)tb_grow(v_lines) = tb_v8886; }
    { const char * tb_v8887 = "    return d < 0 ? 0u : d > 16777215 ? 16777215u : (uint32_t)d;\n"; *(const char * *)tb_grow(v_lines) = tb_v8887; }
    { const char * tb_v8888 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8888; }
    { const char * tb_v8889 = "// треугольник с углами в пределах ±8192 (t меняется: порядок углов); pl — плоскость глубины (3D) или 0\n"; *(const char * *)tb_grow(v_lines) = tb_v8889; }
    { const char * tb_v8890 = "// gpu, cpu — где рисовать (сетку на видеокарте может считать сама видеокарта: тогда здесь только процессор)\n"; *(const char * *)tb_grow(v_lines) = tb_v8890; }
    { const char * tb_v8891 = "static void tb_tri_draw_x(long long *t, long long c, const uint32_t *pl, int gpu, int cpu) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8891; }
    { const char * tb_v8892 = "    if (!tb_tri_prep(t)) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8892; }
    { const char * tb_v8893 = "    if (gpu) { if (pl) tb_gpu_tri3(t, c, pl); else tb_gpu_triangle(t, c); }\n"; *(const char * *)tb_grow(v_lines) = tb_v8893; }
    { const char * tb_v8894 = "    if (cpu) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8894; }
    { const char * tb_v8895 = "        long long xa = t[0], xb = t[0], ya = t[1], yb = t[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v8895; }
    { const char * tb_v8896 = "        for (int i = 2; i < 6; i += 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8896; }
    { const char * tb_v8897 = "            if (t[i] < xa) xa = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v8897; }
    { const char * tb_v8898 = "            if (t[i] > xb) xb = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v8898; }
    { const char * tb_v8899 = "            if (t[i + 1] < ya) ya = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v8899; }
    { const char * tb_v8900 = "            if (t[i + 1] > yb) yb = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v8900; }
    { const char * tb_v8901 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v8901; }
    { const char * tb_v8902 = "        if (xa < 0) xa = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8902; }
    { const char * tb_v8903 = "        if (ya < 0) ya = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8903; }
    { const char * tb_v8904 = "        if (xb > tb_gw - 1) xb = tb_gw - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8904; }
    { const char * tb_v8905 = "        if (yb > tb_gh - 1) yb = tb_gh - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8905; }
    { const char * tb_v8906 = "        for (long long y = ya; y <= yb; y++)\n"; *(const char * *)tb_grow(v_lines) = tb_v8906; }
    { const char * tb_v8907 = "            for (long long x = xa; x <= xb; x++)\n"; *(const char * *)tb_grow(v_lines) = tb_v8907; }
    { const char * tb_v8908 = "                if (tb_tri_edge(t[0], t[1], t[2], t[3], x, y) && tb_tri_edge(t[2], t[3], t[4], t[5], x, y) &&\n"; *(const char * *)tb_grow(v_lines) = tb_v8908; }
    { const char * tb_v8909 = "                    tb_tri_edge(t[4], t[5], t[0], t[1], x, y)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8909; }
    { const char * tb_v8910 = "                    if (pl) {   // 3D: точка видна, если ближе того, что уже нарисовано\n"; *(const char * *)tb_grow(v_lines) = tb_v8910; }
    { const char * tb_v8911 = "                        uint32_t d = tb_tri3_depth(pl, x, y);\n"; *(const char * *)tb_grow(v_lines) = tb_v8911; }
    { const char * tb_v8912 = "                        if (d >= tb_zb[y * tb_gw + x]) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v8912; }
    { const char * tb_v8913 = "                        tb_zb[y * tb_gw + x] = d;\n"; *(const char * *)tb_grow(v_lines) = tb_v8913; }
    { const char * tb_v8914 = "                    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8914; }
    { const char * tb_v8915 = "                    tb_px[y * tb_gw + x] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v8915; }
    { const char * tb_v8916 = "                }\n"; *(const char * *)tb_grow(v_lines) = tb_v8916; }
    { const char * tb_v8917 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8917; }
    { const char * tb_v8918 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8918; }
    { const char * tb_v8919 = "static void tb_tri_draw_i(long long *t, long long c, const uint32_t *pl) { tb_tri_draw_x(t, c, pl, tb_gpu_on, TB_CPU_DRAW); }\n"; *(const char * *)tb_grow(v_lines) = tb_v8919; }
    { const char * tb_v8920 = "// многоугольник с углами-дробями (3D после проекции, огромные треугольники): обрезаем рамкой\n"; *(const char * *)tb_grow(v_lines) = tb_v8920; }
    { const char * tb_v8921 = "// вокруг окна (±2048 точек, но не дальше ±8192), углы округляем, режем веером из первого угла.\n"; *(const char * *)tb_grow(v_lines) = tb_v8921; }
    { const char * tb_v8922 = "// Общие углы округляются одинаково, поэтому соседние треугольники стыкуются без щелей\n"; *(const char * *)tb_grow(v_lines) = tb_v8922; }
    { const char * tb_v8923 = "// округление до ближайшего целого (половина — вверх); быстрее llround, одно и то же везде\n"; *(const char * *)tb_grow(v_lines) = tb_v8923; }
    { const char * tb_v8924 = "TB_INL long long tb_rnd(double x) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8924; }
    { const char * tb_v8925 = "    long long r = (long long)(x + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v8925; }
    { const char * tb_v8926 = "    if ((double)r > x + 0.5) r--;\n"; *(const char * *)tb_grow(v_lines) = tb_v8926; }
    { const char * tb_v8927 = "    return r;\n"; *(const char * *)tb_grow(v_lines) = tb_v8927; }
    { const char * tb_v8928 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8928; }
    { const char * tb_v8929 = "static void tb_poly_draw(double *px, double *py, int n, long long c, const uint32_t *pl) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8929; }
    { const char * tb_v8930 = "    double gx0 = -2048, gy0 = -2048, gx1 = tb_gw + 2048.0, gy1 = tb_gh + 2048.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8930; }
    { const char * tb_v8931 = "    if (gx1 > 8192) gx1 = 8192;\n"; *(const char * *)tb_grow(v_lines) = tb_v8931; }
    { const char * tb_v8932 = "    if (gy1 > 8192) gy1 = 8192;\n"; *(const char * *)tb_grow(v_lines) = tb_v8932; }
    { const char * tb_v8933 = "    double ax[16], ay[16], bx[16], by[16];\n"; *(const char * *)tb_grow(v_lines) = tb_v8933; }
    { const char * tb_v8934 = "    for (int i = 0; i < n; i++) { ax[i] = px[i]; ay[i] = py[i]; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8934; }
    { const char * tb_v8935 = "    for (int side = 0; side < 4 && n > 0; side++) {   // Сазерленд — Ходжман: по одной стороне рамки\n"; *(const char * *)tb_grow(v_lines) = tb_v8935; }
    { const char * tb_v8936 = "        int m = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8936; }
    { const char * tb_v8937 = "        for (int i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8937; }
    { const char * tb_v8938 = "            int j = (i + 1) % n;\n"; *(const char * *)tb_grow(v_lines) = tb_v8938; }
    { const char * tb_v8939 = "            double vi = side == 0 ? ax[i] - gx0 : side == 1 ? gx1 - ax[i] : side == 2 ? ay[i] - gy0 : gy1 - ay[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v8939; }
    { const char * tb_v8940 = "            double vj = side == 0 ? ax[j] - gx0 : side == 1 ? gx1 - ax[j] : side == 2 ? ay[j] - gy0 : gy1 - ay[j];\n"; *(const char * *)tb_grow(v_lines) = tb_v8940; }
    { const char * tb_v8941 = "            if (vi >= 0) { bx[m] = ax[i]; by[m] = ay[i]; m++; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8941; }
    { const char * tb_v8942 = "            if ((vi >= 0) != (vj >= 0)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8942; }
    { const char * tb_v8943 = "                double k = vi / (vi - vj);\n"; *(const char * *)tb_grow(v_lines) = tb_v8943; }
    { const char * tb_v8944 = "                bx[m] = ax[i] + (ax[j] - ax[i]) * k; by[m] = ay[i] + (ay[j] - ay[i]) * k; m++;\n"; *(const char * *)tb_grow(v_lines) = tb_v8944; }
    { const char * tb_v8945 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v8945; }
    { const char * tb_v8946 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v8946; }
    { const char * tb_v8947 = "        n = m;\n"; *(const char * *)tb_grow(v_lines) = tb_v8947; }
    { const char * tb_v8948 = "        for (int i = 0; i < n; i++) { ax[i] = bx[i]; ay[i] = by[i]; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8948; }
    { const char * tb_v8949 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8949; }
    { const char * tb_v8950 = "    if (n < 3) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8950; }
    { const char * tb_v8951 = "    long long rx[16], ry[16];\n"; *(const char * *)tb_grow(v_lines) = tb_v8951; }
    { const char * tb_v8952 = "    for (int i = 0; i < n; i++) { rx[i] = tb_rnd(ax[i]); ry[i] = tb_rnd(ay[i]); }\n"; *(const char * *)tb_grow(v_lines) = tb_v8952; }
    { const char * tb_v8953 = "    for (int i = 1; i + 1 < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8953; }
    { const char * tb_v8954 = "        long long t[6] = { rx[0], ry[0], rx[i], ry[i], rx[i + 1], ry[i + 1] };\n"; *(const char * *)tb_grow(v_lines) = tb_v8954; }
    { const char * tb_v8955 = "        tb_tri_draw_i(t, c, pl);\n"; *(const char * *)tb_grow(v_lines) = tb_v8955; }
    { const char * tb_v8956 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8956; }
    { const char * tb_v8957 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8957; }
    { const char * tb_v8958 = "TB_API void tb_draw_triangle(long long x1, long long y1, long long x2, long long y2, long long x3, long long y3, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8958; }
    { const char * tb_v8959 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8959; }
    { const char * tb_v8960 = "    long long t[6] = { x1, y1, x2, y2, x3, y3 };\n"; *(const char * *)tb_grow(v_lines) = tb_v8960; }
    { const char * tb_v8961 = "    int big = 0;   // (не far/near: на Windows это пустые слова из windows.h)\n"; *(const char * *)tb_grow(v_lines) = tb_v8961; }
    { const char * tb_v8962 = "    for (int i = 0; i < 6; i++) if (t[i] < -8192 || t[i] > 8192) big = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8962; }
    { const char * tb_v8963 = "    if (!big) { tb_tri_draw_i(t, c, 0); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8963; }
    { const char * tb_v8964 = "    double px[3] = { (double)x1, (double)x2, (double)x3 }, py[3] = { (double)y1, (double)y2, (double)y3 };\n"; *(const char * *)tb_grow(v_lines) = tb_v8964; }
    { const char * tb_v8965 = "    tb_poly_draw(px, py, 3, c, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v8965; }
    { const char * tb_v8966 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8966; }
    { const char * tb_v8967 = "// картинка из load_image: левый верхний угол в (x, y); прозрачные точки (меньше 128) не рисуются\n"; *(const char * *)tb_grow(v_lines) = tb_v8967; }
    { const char * tb_v8968 = "TB_API void tb_draw_image(long long id, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8968; }
    { const char * tb_v8969 = "    if (!tb_px || id < 0 || id >= tb_nimg) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8969; }
    { const char * tb_v8970 = "    if (tb_gpu_on) tb_gpu_image(id, x, y);\n"; *(const char * *)tb_grow(v_lines) = tb_v8970; }
    { const char * tb_v8971 = "    if (TB_CPU_DRAW) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8971; }
    { const char * tb_v8972 = "        tb_image *im = &tb_imgs[id];\n"; *(const char * *)tb_grow(v_lines) = tb_v8972; }
    { const char * tb_v8973 = "        const uint32_t *src = tb_imgpx + im->off;\n"; *(const char * *)tb_grow(v_lines) = tb_v8973; }
    { const char * tb_v8974 = "        long long ja = y < 0 ? -y : 0, jb = y + im->h > tb_gh ? tb_gh - y : im->h;\n"; *(const char * *)tb_grow(v_lines) = tb_v8974; }
    { const char * tb_v8975 = "        long long ia = x < 0 ? -x : 0, ib = x + im->w > tb_gw ? tb_gw - x : im->w;\n"; *(const char * *)tb_grow(v_lines) = tb_v8975; }
    { const char * tb_v8976 = "        for (long long j = ja; j < jb; j++) for (long long i = ia; i < ib; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8976; }
    { const char * tb_v8977 = "            uint32_t v = src[j * im->w + i];\n"; *(const char * *)tb_grow(v_lines) = tb_v8977; }
    { const char * tb_v8978 = "            if ((v >> 24) >= 128) tb_px[(y + j) * tb_gw + x + i] = v & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v8978; }
    { const char * tb_v8979 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v8979; }
    { const char * tb_v8980 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8980; }
    { const char * tb_v8981 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8981; }
    { const char * tb_v8982 = "// то же с настоящей прозрачностью: точка = округл(цвет * a / 255) + округл(фон * (255 - a) / 255).\n"; *(const char * *)tb_grow(v_lines) = tb_v8982; }
    { const char * tb_v8983 = "// Две части округляются порознь: так получается одинаково на любой видеокарте (шейдер считает первую часть сам)\n"; *(const char * *)tb_grow(v_lines) = tb_v8983; }
    { const char * tb_v8984 = "TB_API void tb_draw_image_a(long long id, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8984; }
    { const char * tb_v8985 = "    if (!tb_px || id < 0 || id >= tb_nimg) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8985; }
    { const char * tb_v8986 = "    if (tb_gpu_on) tb_gpu_image_a(id, x, y);\n"; *(const char * *)tb_grow(v_lines) = tb_v8986; }
    { const char * tb_v8987 = "    if (TB_CPU_DRAW) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8987; }
    { const char * tb_v8988 = "        tb_image *im = &tb_imgs[id];\n"; *(const char * *)tb_grow(v_lines) = tb_v8988; }
    { const char * tb_v8989 = "        const uint32_t *src = tb_imgpx + im->off;\n"; *(const char * *)tb_grow(v_lines) = tb_v8989; }
    { const char * tb_v8990 = "        long long ja = y < 0 ? -y : 0, jb = y + im->h > tb_gh ? tb_gh - y : im->h;\n"; *(const char * *)tb_grow(v_lines) = tb_v8990; }
    { const char * tb_v8991 = "        long long ia = x < 0 ? -x : 0, ib = x + im->w > tb_gw ? tb_gw - x : im->w;\n"; *(const char * *)tb_grow(v_lines) = tb_v8991; }
    { const char * tb_v8992 = "        for (long long j = ja; j < jb; j++) for (long long i = ia; i < ib; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8992; }
    { const char * tb_v8993 = "            uint32_t v = src[j * im->w + i], a = v >> 24;\n"; *(const char * *)tb_grow(v_lines) = tb_v8993; }
    { const char * tb_v8994 = "            if (a == 0) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v8994; }
    { const char * tb_v8995 = "            uint32_t *d = &tb_px[(y + j) * tb_gw + x + i];\n"; *(const char * *)tb_grow(v_lines) = tb_v8995; }
    { const char * tb_v8996 = "            if (a == 255) { *d = v & 0xFFFFFF; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8996; }
    { const char * tb_v8997 = "            uint32_t o = *d, r = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8997; }
    { const char * tb_v8998 = "            for (int sh = 0; sh <= 16; sh += 8) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8998; }
    { const char * tb_v8999 = "                uint32_t sc = (v >> sh) & 255, dc = (o >> sh) & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v8999; }
    { const char * tb_v9000 = "                uint32_t q = tb_blend_cal ? tb_blend_lut[(sc << 16) | (dc << 8) | a] : (sc * a + 127) / 255 + (dc * (255 - a) + 127) / 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v9000; }
    { const char * tb_v9001 = "                r |= (q > 255 ? 255 : q) << sh;\n"; *(const char * *)tb_grow(v_lines) = tb_v9001; }
    { const char * tb_v9002 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v9002; }
    { const char * tb_v9003 = "            *d = r;\n"; *(const char * *)tb_grow(v_lines) = tb_v9003; }
    { const char * tb_v9004 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v9004; }
    { const char * tb_v9005 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9005; }
    { const char * tb_v9006 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9006; }
    { const char * tb_v9007 = "// текст: буква 8×16, size — во сколько раз крупнее\n"; *(const char * *)tb_grow(v_lines) = tb_v9007; }
    { const char * tb_v9008 = "TB_API void tb_draw_text(long long x, long long y, const char *s, long long size, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9008; }
    { const char * tb_v9009 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9009; }
    { const char * tb_v9010 = "    if (size < 1) size = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9010; }
    { const char * tb_v9011 = "    const unsigned char *p = (const unsigned char *)s;\n"; *(const char * *)tb_grow(v_lines) = tb_v9011; }
    { const char * tb_v9012 = "    long long cx = x;\n"; *(const char * *)tb_grow(v_lines) = tb_v9012; }
    { const char * tb_v9013 = "    while (*p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9013; }
    { const char * tb_v9014 = "        unsigned int u = *p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v9014; }
    { const char * tb_v9015 = "        if (u >= 0x80) {   // UTF-8: собрать букву из 2–4 байт\n"; *(const char * *)tb_grow(v_lines) = tb_v9015; }
    { const char * tb_v9016 = "            int more = u >= 0xF0 ? 3 : u >= 0xE0 ? 2 : u >= 0xC0 ? 1 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9016; }
    { const char * tb_v9017 = "            u &= 0x3F >> more;\n"; *(const char * *)tb_grow(v_lines) = tb_v9017; }
    { const char * tb_v9018 = "            while (more-- > 0 && (*p & 0xC0) == 0x80) u = (u << 6) | (*p++ & 0x3F);\n"; *(const char * *)tb_grow(v_lines) = tb_v9018; }
    { const char * tb_v9019 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v9019; }
    { const char * tb_v9020 = "        if (u == 0x2013 || u == 0x2014) u = '-';\n"; *(const char * *)tb_grow(v_lines) = tb_v9020; }
    { const char * tb_v9021 = "        if (u == 0xD7) u = 'x';   // × как x (размер окна 640×400)\n"; *(const char * *)tb_grow(v_lines) = tb_v9021; }
    { const char * tb_v9022 = "        if (u == 0xAB || u == 0xBB || u == 0x201C || u == 0x201D) u = '\"';\n"; *(const char * *)tb_grow(v_lines) = tb_v9022; }
    { const char * tb_v9023 = "        if (u == '\\n') { cx = x; y += 16 * size; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9023; }
    { const char * tb_v9024 = "        int g = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9024; }
    { const char * tb_v9025 = "        if (u >= 32 && u <= 126) g = (int)u - 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v9025; }
    { const char * tb_v9026 = "        else if (u >= 0x410 && u <= 0x44F) g = 95 + (int)(u - 0x410);\n"; *(const char * *)tb_grow(v_lines) = tb_v9026; }
    { const char * tb_v9027 = "        else if (u == 0x401) g = 159;\n"; *(const char * *)tb_grow(v_lines) = tb_v9027; }
    { const char * tb_v9028 = "        else if (u == 0x451) g = 160;\n"; *(const char * *)tb_grow(v_lines) = tb_v9028; }
    { const char * tb_v9029 = "        if (g < 0) g = '?' - 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v9029; }
    { const char * tb_v9030 = "        if (tb_gpu_on && g != 0) tb_gpu_glyph(cx, y, g, size, c);   // 0 — пробел, рисовать нечего\n"; *(const char * *)tb_grow(v_lines) = tb_v9030; }
    { const char * tb_v9031 = "        if (TB_CPU_DRAW)\n"; *(const char * *)tb_grow(v_lines) = tb_v9031; }
    { const char * tb_v9032 = "            for (int row = 0; row < 16; row++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9032; }
    { const char * tb_v9033 = "                unsigned char bits = tb_font[g][row];\n"; *(const char * *)tb_grow(v_lines) = tb_v9033; }
    { const char * tb_v9034 = "                for (int col = 0; col < 8; col++)\n"; *(const char * *)tb_grow(v_lines) = tb_v9034; }
    { const char * tb_v9035 = "                    if (bits & (0x80 >> col)) tb_cpu_rect(cx + col * size, y + row * size, size, size, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v9035; }
    { const char * tb_v9036 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v9036; }
    { const char * tb_v9037 = "        cx += 8 * size;\n"; *(const char * *)tb_grow(v_lines) = tb_v9037; }
    { const char * tb_v9038 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9038; }
    { const char * tb_v9039 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9039; }
    { const char * tb_v9040 = "// ---------- 3D: сетки и камера ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v9040; }
    { const char * tb_v9041 = "// Сетка — список треугольников в мире (x вправо, y вверх, z вперёд). draw_mesh поворачивает её\n"; *(const char * *)tb_grow(v_lines) = tb_v9041; }
    { const char * tb_v9042 = "// вокруг вертикали, ставит в точку, смотрит камерой (угол обзора 60°), обрезает всё ближе 0.05\n"; *(const char * *)tb_grow(v_lines) = tb_v9042; }
    { const char * tb_v9043 = "// и рисует. Ближнее закрывает дальнее: у каждой точки есть глубина (tb_zb на процессоре,\n"; *(const char * *)tb_grow(v_lines) = tb_v9043; }
    { const char * tb_v9044 = "// буфер глубины на видеокарте). Углы, обрезка и плоскость глубины считаются на процессоре,\n"; *(const char * *)tb_grow(v_lines) = tb_v9044; }
    { const char * tb_v9045 = "// а глубину каждой точки видеокарта и процессор считают одной и той же целой формулой:\n"; *(const char * *)tb_grow(v_lines) = tb_v9045; }
    { const char * tb_v9046 = "// кадры совпадают точка в точку.\n"; *(const char * *)tb_grow(v_lines) = tb_v9046; }
    { const char * tb_v9047 = "// сетка: свои углы без повторов (у куба 8, а не 36) и треугольники как три номера угла.\n"; *(const char * *)tb_grow(v_lines) = tb_v9047; }
    { const char * tb_v9048 = "// Каждый угол поворачивается и проецируется один раз на draw_mesh, а не в каждом своём треугольнике\n"; *(const char * *)tb_grow(v_lines) = tb_v9048; }
    { const char * tb_v9049 = "// vi — те же углы в целых (× 4096, по 4 числа: x, y, z, 0) для 3D на видеокарте; bb — коробка вокруг углов;\n"; *(const char * *)tb_grow(v_lines) = tb_v9049; }
    { const char * tb_v9050 = "// big — есть угол дальше 262 144 от центра сетки (в целые не влезает: только старый путь);\n"; *(const char * *)tb_grow(v_lines) = tb_v9050; }
    { const char * tb_v9051 = "// cull — какие грани не видны (0 — сетка не закрытая, считать все), cullok — cull уже посчитан;\n"; *(const char * *)tb_grow(v_lines) = tb_v9051; }
    { const char * tb_v9052 = "// gv, gt — где углы и треугольники сетки в памяти видеокарты; gused — в какой пачке видеокарта её рисует\n"; *(const char * *)tb_grow(v_lines) = tb_v9052; }
    { const char * tb_v9053 = "typedef struct { double *v; long long nv, capv; uint32_t *t, *c; long long n, cap; long long *hk; long long hcap;\n"; *(const char * *)tb_grow(v_lines) = tb_v9053; }
    { const char * tb_v9054 = "    int32_t *vi; double bb[6]; int big, cull, cullok; long long gv, gt, gused;\n"; *(const char * *)tb_grow(v_lines) = tb_v9054; }
    { const char * tb_v9055 = "    long long nch, *chr; double *chs, bs[4]; int chok; } tb_mesh;   // куски: chr — (первый треугольник, сколько), chs и bs — шары (центр, радиус)\n"; *(const char * *)tb_grow(v_lines) = tb_v9055; }
    { const char * tb_v9056 = "TB_API tb_mesh *tb_meshes = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9056; }
    { const char * tb_v9057 = "TB_API long long tb_nmesh = 0, tb_capmesh = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9057; }
    { const char * tb_v9058 = "TB_API double tb_cam[9] = { 0, 0, -5,  1, 0, 0,  0, 1, 0 };   // где камера, вправо, вверх\n"; *(const char * *)tb_grow(v_lines) = tb_v9058; }
    { const char * tb_v9059 = "TB_API double tb_camf[3] = { 0, 0, 1 };                      // вперёд\n"; *(const char * *)tb_grow(v_lines) = tb_v9059; }
    { const char * tb_v9060 = "TB_API long long tb_mesh_new(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9060; }
    { const char * tb_v9061 = "    if (tb_nmesh == tb_capmesh) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9061; }
    { const char * tb_v9062 = "        tb_capmesh = tb_capmesh ? tb_capmesh * 2 : 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v9062; }
    { const char * tb_v9063 = "        tb_meshes = (tb_mesh *)realloc(tb_meshes, sizeof(tb_mesh) * tb_capmesh);\n"; *(const char * *)tb_grow(v_lines) = tb_v9063; }
    { const char * tb_v9064 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9064; }
    { const char * tb_v9065 = "    memset(&tb_meshes[tb_nmesh], 0, sizeof(tb_mesh));\n"; *(const char * *)tb_grow(v_lines) = tb_v9065; }
    { const char * tb_v9066 = "    tb_meshes[tb_nmesh].gused = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9066; }
    { const char * tb_v9067 = "    return tb_nmesh++;\n"; *(const char * *)tb_grow(v_lines) = tb_v9067; }
    { const char * tb_v9068 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9068; }
    { const char * tb_v9069 = "TB_INL uint64_t tb_vhash(const double *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9069; }
    { const char * tb_v9070 = "    uint64_t h = 1469598103934665603ULL, w[3];\n"; *(const char * *)tb_grow(v_lines) = tb_v9070; }
    { const char * tb_v9071 = "    memcpy(w, p, 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v9071; }
    { const char * tb_v9072 = "    for (int i = 0; i < 3; i++) { h ^= w[i]; h *= 1099511628211ULL; h ^= h >> 29; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9072; }
    { const char * tb_v9073 = "    return h;\n"; *(const char * *)tb_grow(v_lines) = tb_v9073; }
    { const char * tb_v9074 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9074; }
    { const char * tb_v9075 = "// номер угла (x, y, z) в сетке: такой же уже есть — тот же номер (таблица с открытой адресацией)\n"; *(const char * *)tb_grow(v_lines) = tb_v9075; }
    { const char * tb_v9076 = "static uint32_t tb_mesh_vertex(tb_mesh *m, double x, double y, double z) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9076; }
    { const char * tb_v9077 = "    double p[3] = { x + 0.0, y + 0.0, z + 0.0 };   // + 0.0: -0 и 0 — один угол\n"; *(const char * *)tb_grow(v_lines) = tb_v9077; }
    { const char * tb_v9078 = "    if (m->nv * 2 >= m->hcap) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9078; }
    { const char * tb_v9079 = "        long long nc = m->hcap ? m->hcap * 2 : 64;\n"; *(const char * *)tb_grow(v_lines) = tb_v9079; }
    { const char * tb_v9080 = "        long long *nk = (long long *)malloc(sizeof(long long) * nc);\n"; *(const char * *)tb_grow(v_lines) = tb_v9080; }
    { const char * tb_v9081 = "        for (long long i = 0; i < nc; i++) nk[i] = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9081; }
    { const char * tb_v9082 = "        for (long long v = 0; v < m->nv; v++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9082; }
    { const char * tb_v9083 = "            uint64_t h = tb_vhash(m->v + 3 * v) & (uint64_t)(nc - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v9083; }
    { const char * tb_v9084 = "            while (nk[h] >= 0) h = (h + 1) & (uint64_t)(nc - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v9084; }
    { const char * tb_v9085 = "            nk[h] = v;\n"; *(const char * *)tb_grow(v_lines) = tb_v9085; }
    { const char * tb_v9086 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v9086; }
    { const char * tb_v9087 = "        free(m->hk); m->hk = nk; m->hcap = nc;\n"; *(const char * *)tb_grow(v_lines) = tb_v9087; }
    { const char * tb_v9088 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9088; }
    { const char * tb_v9089 = "    uint64_t h = tb_vhash(p) & (uint64_t)(m->hcap - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v9089; }
    { const char * tb_v9090 = "    while (m->hk[h] >= 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9090; }
    { const char * tb_v9091 = "        if (memcmp(m->v + 3 * m->hk[h], p, 24) == 0) return (uint32_t)m->hk[h];\n"; *(const char * *)tb_grow(v_lines) = tb_v9091; }
    { const char * tb_v9092 = "        h = (h + 1) & (uint64_t)(m->hcap - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v9092; }
    { const char * tb_v9093 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9093; }
    { const char * tb_v9094 = "    if (m->nv == m->capv) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9094; }
    { const char * tb_v9095 = "        m->capv = m->capv ? m->capv * 2 : 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v9095; }
    { const char * tb_v9096 = "        m->v = (double *)realloc(m->v, sizeof(double) * 3 * m->capv);\n"; *(const char * *)tb_grow(v_lines) = tb_v9096; }
    { const char * tb_v9097 = "        m->vi = (int32_t *)realloc(m->vi, sizeof(int32_t) * 4 * m->capv);\n"; *(const char * *)tb_grow(v_lines) = tb_v9097; }
    { const char * tb_v9098 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9098; }
    { const char * tb_v9099 = "    memcpy(m->v + 3 * m->nv, p, 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v9099; }
    { const char * tb_v9100 = "    for (int i = 0; i < 3; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9100; }
    { const char * tb_v9101 = "        if (m->nv == 0 || p[i] < m->bb[i]) m->bb[i] = p[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v9101; }
    { const char * tb_v9102 = "        if (m->nv == 0 || p[i] > m->bb[3 + i]) m->bb[3 + i] = p[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v9102; }
    { const char * tb_v9103 = "        if (!(fabs(p[i]) < 262144)) m->big = 1;   // и NaN тоже\n"; *(const char * *)tb_grow(v_lines) = tb_v9103; }
    { const char * tb_v9104 = "        m->vi[4 * m->nv + i] = m->big ? 0 : (int32_t)tb_rnd(p[i] * 4096);\n"; *(const char * *)tb_grow(v_lines) = tb_v9104; }
    { const char * tb_v9105 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9105; }
    { const char * tb_v9106 = "    m->vi[4 * m->nv + 3] = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9106; }
    { const char * tb_v9107 = "    m->hk[h] = m->nv;\n"; *(const char * *)tb_grow(v_lines) = tb_v9107; }
    { const char * tb_v9108 = "    return (uint32_t)m->nv++;\n"; *(const char * *)tb_grow(v_lines) = tb_v9108; }
    { const char * tb_v9109 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9109; }
    { const char * tb_v9110 = "TB_API void tb_mesh_add(long long id, double x1, double y1, double z1, double x2, double y2, double z2,\n"; *(const char * *)tb_grow(v_lines) = tb_v9110; }
    { const char * tb_v9111 = "                        double x3, double y3, double z3, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9111; }
    { const char * tb_v9112 = "    if (id < 0 || id >= tb_nmesh) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9112; }
    { const char * tb_v9113 = "    tb_mesh *m = &tb_meshes[id];\n"; *(const char * *)tb_grow(v_lines) = tb_v9113; }
    { const char * tb_v9114 = "    // видеокарта ещё не нарисовала эту сетку из текущей пачки: сначала отдать пачку (там старая сетка)\n"; *(const char * *)tb_grow(v_lines) = tb_v9114; }
    { const char * tb_v9115 = "    if (tb_gpu_on && m->gused == tb_gbatch) tb_gpu_flush(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v9115; }
    { const char * tb_v9116 = "    tb_mesh_gdirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9116; }
    { const char * tb_v9117 = "    m->cullok = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9117; }
