    { const char * tb_v9135 = "    if (fabs(f[1]) > 0.9999) { up[1] = 0; up[2] = 1; }   // смотрим прямо вверх или вниз\n"; *(const char * *)tb_grow(v_lines) = tb_v9135; }
    { const char * tb_v9136 = "    double r[3] = { up[1] * f[2] - up[2] * f[1], up[2] * f[0] - up[0] * f[2], up[0] * f[1] - up[1] * f[0] };\n"; *(const char * *)tb_grow(v_lines) = tb_v9136; }
