    { const char * tb_v9142 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9142; }
    { const char * tb_v9143 = "// плоскость глубины по трём точкам экрана (x, y, D); 0 — треугольник ребром к нам, рисовать нечего\n"; *(const char * *)tb_grow(v_lines) = tb_v9143; }
