    { const char * tb_v9187 = "        v->cx = wx * tb_cam[3] + wy * tb_cam[4] + wz * tb_cam[5];\n"; *(const char * *)tb_grow(v_lines) = tb_v9187; }
    { const char * tb_v9188 = "        v->cy = wx * tb_cam[6] + wy * tb_cam[7] + wz * tb_cam[8];\n"; *(const char * *)tb_grow(v_lines) = tb_v9188; }
    { const char * tb_v9189 = "        v->cz = wx * tb_camf[0] + wy * tb_camf[1] + wz * tb_camf[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v9189; }
