    { const char * tb_v9211 = "                tb_tri_draw_i(q, m->c[t], pl);\n"; *(const char * *)tb_grow(v_lines) = tb_v9211; }
    { const char * tb_v9212 = "            } else tb_poly_draw(sx, sy, 3, m->c[t], pl);\n"; *(const char * *)tb_grow(v_lines) = tb_v9212; }
    { const char * tb_v9213 = "            continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v9213; }
    { const char * tb_v9214 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v9214; }
    { const char * tb_v9215 = "        // часть треугольника за камерой: обрезаем всё ближе zn — выходит 0, 3 или 4 угла\n"; *(const char * *)tb_grow(v_lines) = tb_v9215; }
    { const char * tb_v9216 = "        tb_3v *vs[3] = { v0, v1, v2 };\n"; *(const char * *)tb_grow(v_lines) = tb_v9216; }
