    { const char * tb_v9245 = "// фокус экрана × 256 (угол обзора 60°)\n"; *(const char * *)tb_grow(v_lines) = tb_v9245; }
    { const char * tb_v9246 = "TB_INL long long tb_m3_f(void) { return tb_rnd(tb_gh / 2.0 / tan(30 * 3.14159265358979323846 / 180) * 256); }\n"; *(const char * *)tb_grow(v_lines) = tb_v9246; }
    { const char * tb_v9247 = "// угол сетки p (× 4096) по записи r: место на экране (целые точки) и глубина D = 2^24 - 2^24 * zn / z, zn = 205 / 4096\n"; *(const char * *)tb_grow(v_lines) = tb_v9247; }
    { const char * tb_v9248 = "TB_INL void tb_m3_corner(const int32_t *r, const int32_t *p, long long f, long long *o) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9248; }
    { const char * tb_v9249 = "    long long c[3];\n"; *(const char * *)tb_grow(v_lines) = tb_v9249; }
    { const char * tb_v9250 = "    for (int k = 0; k < 3; k++)\n"; *(const char * *)tb_grow(v_lines) = tb_v9250; }
    { const char * tb_v9251 = "        c[k] = (((long long)r[4 * k] * p[0] + (long long)r[4 * k + 1] * p[1] + (long long)r[4 * k + 2] * p[2]) >> 30) + r[4 * k + 3];\n"; *(const char * *)tb_grow(v_lines) = tb_v9251; }
    { const char * tb_v9252 = "    o[0] = ((long long)tb_gw * 128 + tb_fdiv(f * c[0], c[2]) + 128) >> 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v9252; }
    { const char * tb_v9253 = "    o[1] = ((long long)tb_gh * 128 - tb_fdiv(f * c[1], c[2]) + 128) >> 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v9253; }
    { const char * tb_v9254 = "    o[2] = 16777216 - tb_fdiv(205LL << 24, c[2]);\n"; *(const char * *)tb_grow(v_lines) = tb_v9254; }
    { const char * tb_v9255 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9255; }
    { const char * tb_v9256 = "// треугольник a, b, c (x, y, D): 0 — рисовать нечего (ребром к нам или невидимая грань); иначе углы\n"; *(const char * *)tb_grow(v_lines) = tb_v9256; }
    { const char * tb_v9257 = "// по кругу «как надо» в t и плоскость глубины в pl — то же, что tb_tri3_plane, только в целых\n"; *(const char * *)tb_grow(v_lines) = tb_v9257; }
    { const char * tb_v9258 = "TB_INL int tb_m3_tri(const long long *a, const long long *b, const long long *c, int cull, long long *t, uint32_t *pl) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9258; }
    { const char * tb_v9259 = "    long long area = (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v9259; }
    { const char * tb_v9260 = "    if (area == 0 || (cull > 0 && area > 0) || (cull < 0 && area < 0)) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9260; }
    { const char * tb_v9261 = "    if (area < 0) { const long long *k = b; b = c; c = k; area = -area; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9261; }
    { const char * tb_v9262 = "    long long e1x = b[0] - a[0], e1y = b[1] - a[1], e2x = c[0] - a[0], e2y = c[1] - a[1], d1 = b[2] - a[2], d2 = c[2] - a[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v9262; }
    { const char * tb_v9263 = "    long long A = tb_fdiv(64 * (d1 * e2y - d2 * e1y) + area, 2 * area), B = tb_fdiv(64 * (d2 * e1x - d1 * e2x) + area, 2 * area);\n"; *(const char * *)tb_grow(v_lines) = tb_v9263; }
    { const char * tb_v9264 = "    long long C = 64 * a[2] - 2 * A * a[0] - 2 * B * a[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v9264; }
    { const char * tb_v9265 = "    pl[0] = (uint32_t)A; pl[1] = (uint32_t)B; pl[2] = (uint32_t)C;\n"; *(const char * *)tb_grow(v_lines) = tb_v9265; }
    { const char * tb_v9266 = "    t[0] = a[0]; t[1] = a[1]; t[2] = b[0]; t[3] = b[1]; t[4] = c[0]; t[5] = c[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v9266; }
    { const char * tb_v9267 = "    return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9267; }
    { const char * tb_v9268 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9268; }
    { const char * tb_v9269 = "// закрытая сетка (каждая сторона треугольника есть и в обратную сторону у соседа): грань, повёрнутая\n"; *(const char * *)tb_grow(v_lines) = tb_v9269; }
    { const char * tb_v9270 = "// от камеры, всегда закрыта другими гранями — и у куба снаружи, и у комнаты изнутри (грани внутрь).\n"; *(const char * *)tb_grow(v_lines) = tb_v9270; }
    { const char * tb_v9271 = "// Повёрнута от камеры = на экране по часовой стрелке (площадь < 0). 0 — рисовать все, -1 — пропускать такие\n"; *(const char * *)tb_grow(v_lines) = tb_v9271; }
    { const char * tb_v9272 = "static int tb_cmp_u64(const void *a, const void *b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9272; }
    { const char * tb_v9273 = "    uint64_t x = *(const uint64_t *)a, y = *(const uint64_t *)b;\n"; *(const char * *)tb_grow(v_lines) = tb_v9273; }
    { const char * tb_v9274 = "    return x < y ? -1 : x > y;\n"; *(const char * *)tb_grow(v_lines) = tb_v9274; }
    { const char * tb_v9275 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9275; }
    { const char * tb_v9276 = "static int tb_mesh_cull(tb_mesh *m) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9276; }
    { const char * tb_v9277 = "    if (m->cullok) return m->cull;\n"; *(const char * *)tb_grow(v_lines) = tb_v9277; }
    { const char * tb_v9278 = "    m->cullok = 1; m->cull = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9278; }
    { const char * tb_v9279 = "    long long ne = 3 * m->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v9279; }
    { const char * tb_v9280 = "    uint64_t *e = (uint64_t *)malloc(sizeof(uint64_t) * (size_t)(ne ? ne : 1));\n"; *(const char * *)tb_grow(v_lines) = tb_v9280; }
    { const char * tb_v9281 = "    double vol = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9281; }
    { const char * tb_v9282 = "    for (long long t = 0; t < m->n; t++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9282; }
    { const char * tb_v9283 = "        const uint32_t *ti = m->t + 3 * t;\n"; *(const char * *)tb_grow(v_lines) = tb_v9283; }
    { const char * tb_v9284 = "        for (int k = 0; k < 3; k++) e[3 * t + k] = ((uint64_t)ti[k] << 32) | ti[(k + 1) % 3];\n"; *(const char * *)tb_grow(v_lines) = tb_v9284; }
    { const char * tb_v9285 = "        const double *p = m->v + 3 * ti[0], *q = m->v + 3 * ti[1], *r = m->v + 3 * ti[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v9285; }
    { const char * tb_v9286 = "        vol += p[0] * (q[1] * r[2] - q[2] * r[1]) + p[1] * (q[2] * r[0] - q[0] * r[2]) + p[2] * (q[0] * r[1] - q[1] * r[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v9286; }
    { const char * tb_v9287 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9287; }
    { const char * tb_v9288 = "    qsort(e, (size_t)ne, sizeof(uint64_t), tb_cmp_u64);\n"; *(const char * *)tb_grow(v_lines) = tb_v9288; }
    { const char * tb_v9289 = "    int closed = ne > 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9289; }
    { const char * tb_v9290 = "    for (long long i = 0; i < ne && closed; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9290; }
    { const char * tb_v9291 = "        if (i + 1 < ne && e[i] == e[i + 1]) closed = 0;   // одна сторона дважды в одну сторону\n"; *(const char * *)tb_grow(v_lines) = tb_v9291; }
    { const char * tb_v9292 = "        uint64_t back = (e[i] << 32) | (e[i] >> 32);\n"; *(const char * *)tb_grow(v_lines) = tb_v9292; }
    { const char * tb_v9293 = "        if ((uint32_t)e[i] == (uint32_t)(e[i] >> 32) || !bsearch(&back, e, (size_t)ne, sizeof(uint64_t), tb_cmp_u64)) closed = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9293; }
    { const char * tb_v9294 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9294; }
    { const char * tb_v9295 = "    free(e);\n"; *(const char * *)tb_grow(v_lines) = tb_v9295; }
    { const char * tb_v9296 = "    if (closed && fabs(vol) > 1e-12) m->cull = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9296; }
    { const char * tb_v9297 = "    return m->cull;\n"; *(const char * *)tb_grow(v_lines) = tb_v9297; }
    { const char * tb_v9298 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9298; }
    { const char * tb_v9299 = "// сетки для видеокарты: у каждой сначала углы (x, y, z, 0), потом треугольники (номера углов, цвет)\n"; *(const char * *)tb_grow(v_lines) = tb_v9299; }
    { const char * tb_v9300 = "TB_API long long tb_mesh_pack(int32_t *dst) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9300; }
    { const char * tb_v9301 = "    long long at = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9301; }
    { const char * tb_v9302 = "    for (long long i = 0; i < tb_nmesh; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9302; }
    { const char * tb_v9303 = "        tb_mesh *m = &tb_meshes[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v9303; }
    { const char * tb_v9304 = "        m->gv = at; m->gt = at + m->nv;\n"; *(const char * *)tb_grow(v_lines) = tb_v9304; }
    { const char * tb_v9305 = "        if (dst) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9305; }
    { const char * tb_v9306 = "            memcpy(dst + 4 * at, m->vi, sizeof(int32_t) * 4 * (size_t)m->nv);\n"; *(const char * *)tb_grow(v_lines) = tb_v9306; }
    { const char * tb_v9307 = "            for (long long t = 0; t < m->n; t++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9307; }
    { const char * tb_v9308 = "                int32_t *o = dst + 4 * (m->gt + t);\n"; *(const char * *)tb_grow(v_lines) = tb_v9308; }
    { const char * tb_v9309 = "                for (int k = 0; k < 3; k++) o[k] = (int32_t)(m->t[3 * t + k] + m->gv);\n"; *(const char * *)tb_grow(v_lines) = tb_v9309; }
    { const char * tb_v9310 = "                o[3] = (int32_t)(m->c[t] & 0xFFFFFF);\n"; *(const char * *)tb_grow(v_lines) = tb_v9310; }
    { const char * tb_v9311 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v9311; }
    { const char * tb_v9312 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v9312; }
    { const char * tb_v9313 = "        at += m->nv + m->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v9313; }
    { const char * tb_v9314 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9314; }
    { const char * tb_v9315 = "    return at;\n"; *(const char * *)tb_grow(v_lines) = tb_v9315; }
    { const char * tb_v9316 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9316; }
    { const char * tb_v9317 = "TB_API void tb_mesh_gpc(const tb_ginst *g, int slot, tb_gpc *pc) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9317; }
    { const char * tb_v9318 = "    tb_mesh *m = &tb_meshes[g->x0];\n"; *(const char * *)tb_grow(v_lines) = tb_v9318; }
    { const char * tb_v9319 = "    pc->size[0] = (float)tb_gw; pc->size[1] = (float)tb_gh;\n"; *(const char * *)tb_grow(v_lines) = tb_v9319; }
    { const char * tb_v9320 = "    pc->tbase = (int32_t)(m->gt + g->ox); pc->ntri = g->oy; pc->rbase = (slot * TB_GR_CAP + g->x1) * 3;\n"; *(const char * *)tb_grow(v_lines) = tb_v9320; }
    { const char * tb_v9321 = "    pc->f = (int32_t)tb_m3_f(); pc->gw = tb_gw; pc->gh = tb_gh; pc->cull = g->y0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9321; }
    { const char * tb_v9322 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9322; }
    { const char * tb_v9323 = "TB_API long long *tb_3i = 0;   // углы сетки после камеры в целых: x, y, D\n"; *(const char * *)tb_grow(v_lines) = tb_v9323; }
    { const char * tb_v9324 = "TB_API long long tb_3icap = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9324; }
    { const char * tb_v9325 = "// шар сетки или куска (центр в сетке, радиус) после камеры: 0 — не видно совсем (за камерой или вне экрана\n"; *(const char * *)tb_grow(v_lines) = tb_v9325; }
    { const char * tb_v9326 = "// с запасом 2 точки), 1 — целые годятся (весь перед камерой, на экране не дальше ±8100 точек), 2 — старый путь\n"; *(const char * *)tb_grow(v_lines) = tb_v9326; }
    { const char * tb_v9327 = "static int tb_m3_test(const double *sp, double M[3][3], const double *T, double f, int big) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9327; }
    { const char * tb_v9328 = "    double cc[3], rad = sp[3];\n"; *(const char * *)tb_grow(v_lines) = tb_v9328; }
    { const char * tb_v9329 = "    for (int k = 0; k < 3; k++) cc[k] = M[k][0] * sp[0] + M[k][1] * sp[1] + M[k][2] * sp[2] + T[k];\n"; *(const char * *)tb_grow(v_lines) = tb_v9329; }
    { const char * tb_v9330 = "    if (cc[2] + rad < 205.0 / 4096) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9330; }
    { const char * tb_v9331 = "    double hw = tb_gw / 2.0 + 2, hh = tb_gh / 2.0 + 2, lx = sqrt(f * f + hw * hw), ly = sqrt(f * f + hh * hh);\n"; *(const char * *)tb_grow(v_lines) = tb_v9331; }
    { const char * tb_v9332 = "    if ((f * cc[0] - hw * cc[2]) / lx > rad || (-f * cc[0] - hw * cc[2]) / lx > rad) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9332; }
    { const char * tb_v9333 = "    if ((f * cc[1] - hh * cc[2]) / ly > rad || (-f * cc[1] - hh * cc[2]) / ly > rad) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9333; }
    { const char * tb_v9334 = "    double zmin = cc[2] - rad;\n"; *(const char * *)tb_grow(v_lines) = tb_v9334; }
    { const char * tb_v9335 = "    int ok = !big && zmin >= 0.12 && fabs(T[0]) < 400000 && fabs(T[1]) < 400000 && fabs(T[2]) < 400000 &&\n"; *(const char * *)tb_grow(v_lines) = tb_v9335; }
    { const char * tb_v9336 = "             fabs(cc[0]) + rad < 400000 && fabs(cc[1]) + rad < 400000 && cc[2] + rad < 400000;\n"; *(const char * *)tb_grow(v_lines) = tb_v9336; }
    { const char * tb_v9337 = "    if (ok) ok = tb_gw / 2.0 + f * (fabs(cc[0]) + rad) / zmin < 8100 && tb_gh / 2.0 + f * (fabs(cc[1]) + rad) / zmin < 8100;\n"; *(const char * *)tb_grow(v_lines) = tb_v9337; }
    { const char * tb_v9338 = "    return ok ? 1 : 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v9338; }
    { const char * tb_v9339 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9339; }
    { const char * tb_v9340 = "// один draw_mesh в целых: запись (одна на вызов, в текущем наборе) и куски треугольников\n"; *(const char * *)tb_grow(v_lines) = tb_v9340; }
    { const char * tb_v9341 = "typedef struct { tb_mesh *m; long long id; int cull; long long ri, rbatch; tb_grec rec; } tb_m3_go;\n"; *(const char * *)tb_grow(v_lines) = tb_v9341; }
    { const char * tb_v9342 = "TB_API long long *tb_3ist = 0, tb_3igen = 0;   // какой угол уже посчитан в этом вызове (процессор)\n"; *(const char * *)tb_grow(v_lines) = tb_v9342; }
    { const char * tb_v9343 = "static void tb_m3_draw(tb_m3_go *go, long long t0, long long tn) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9343; }
    { const char * tb_v9344 = "    tb_mesh *m = go->m;\n"; *(const char * *)tb_grow(v_lines) = tb_v9344; }
    { const char * tb_v9345 = "    if (tb_gpu_on && tb_gpu_mesh) {   // видеокарта считает сама: только запись и «нарисуй треугольники t0.. из сетки»\n"; *(const char * *)tb_grow(v_lines) = tb_v9345; }
    { const char * tb_v9346 = "        if (tb_gin == TB_GI_CAP || (go->rbatch != tb_gbatch && tb_grn == TB_GR_CAP)) tb_gpu_flush(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v9346; }
    { const char * tb_v9347 = "        if (go->rbatch != tb_gbatch) {   // запись этого вызова ещё не в текущем наборе\n"; *(const char * *)tb_grow(v_lines) = tb_v9347; }
    { const char * tb_v9348 = "            go->ri = tb_grn++;\n"; *(const char * *)tb_grow(v_lines) = tb_v9348; }
    { const char * tb_v9349 = "            go->rbatch = tb_gbatch;\n"; *(const char * *)tb_grow(v_lines) = tb_v9349; }
    { const char * tb_v9350 = "            tb_grec_p[tb_gslot * TB_GR_CAP + go->ri] = go->rec;\n"; *(const char * *)tb_grow(v_lines) = tb_v9350; }
    { const char * tb_v9351 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v9351; }
    { const char * tb_v9352 = "        tb_ginst *g = tb_gin ? &tb_gi[tb_gin - 1] : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9352; }
    { const char * tb_v9353 = "        if (g && g->m == 3u && g->x0 == (int32_t)go->id && g->y0 == go->cull && g->ox == t0 && g->oy == tn &&\n"; *(const char * *)tb_grow(v_lines) = tb_v9353; }
    { const char * tb_v9354 = "            g->x1 + g->y1 == go->ri && (long long)(g->y1 + 1) * tn < 2000000000) g->y1++;   // та же сетка подряд: одним вызовом\n"; *(const char * *)tb_grow(v_lines) = tb_v9354; }
    { const char * tb_v9355 = "        else tb_gpu_add(go->id, go->cull, go->ri, 1, t0, tn, 0, 3u);\n"; *(const char * *)tb_grow(v_lines) = tb_v9355; }
    { const char * tb_v9356 = "        m->gused = tb_gbatch;\n"; *(const char * *)tb_grow(v_lines) = tb_v9356; }
    { const char * tb_v9357 = "        if (!TB_CPU_DRAW) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9357; }
    { const char * tb_v9358 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9358; }
    { const char * tb_v9359 = "    // процессор: та же целая формула (кадр для сверки, или видеокарта без своего 3D, или без видеокарты)\n"; *(const char * *)tb_grow(v_lines) = tb_v9359; }
    { const char * tb_v9360 = "    int gpu = tb_gpu_on && !tb_gpu_mesh, cpu = TB_CPU_DRAW;\n"; *(const char * *)tb_grow(v_lines) = tb_v9360; }
    { const char * tb_v9361 = "    if (m->nv * 3 > tb_3icap) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9361; }
    { const char * tb_v9362 = "        tb_3icap = m->nv * 6;\n"; *(const char * *)tb_grow(v_lines) = tb_v9362; }
    { const char * tb_v9363 = "        tb_3i = (long long *)realloc(tb_3i, sizeof(long long) * tb_3icap);\n"; *(const char * *)tb_grow(v_lines) = tb_v9363; }
    { const char * tb_v9364 = "        tb_3ist = (long long *)realloc(tb_3ist, sizeof(long long) * tb_3icap / 3);\n"; *(const char * *)tb_grow(v_lines) = tb_v9364; }
    { const char * tb_v9365 = "        memset(tb_3ist, 0, sizeof(long long) * (tb_3icap / 3));\n"; *(const char * *)tb_grow(v_lines) = tb_v9365; }
    { const char * tb_v9366 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9366; }
    { const char * tb_v9367 = "    long long fq = tb_m3_f(), gen = ++tb_3igen;\n"; *(const char * *)tb_grow(v_lines) = tb_v9367; }
