    { const char * tb_v9514 = "// буфер обмена системы: текст, который копируют и вставляют между программами (Cmd/Ctrl+C, V)\n"; *(const char * *)tb_grow(v_lines) = tb_v9514; }
    { const char * tb_v9515 = "TB_API const char *tb_clipboard_get(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9515; }
    { const char * tb_v9516 = "    char *got = tb_gfx_clip_get();   // malloc или 0\n"; *(const char * *)tb_grow(v_lines) = tb_v9516; }
    { const char * tb_v9517 = "    size_t n = got ? strlen(got) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9517; }
