    { const char * tb_v9525 = "// вид стрелки мыши над окном\n"; *(const char * *)tb_grow(v_lines) = tb_v9525; }
    { const char * tb_v9526 = "TB_API void tb_set_cursor(const char *name, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9526; }
    { const char * tb_v9527 = "    static const char *names[] = { \"arrow\", \"hand\", \"text\", \"move\", \"resize_x\", \"resize_y\", \"wait\", \"none\" };\n"; *(const char * *)tb_grow(v_lines) = tb_v9527; }
