    { const char * tb_v9530 = "    char buf[200];\n"; *(const char * *)tb_grow(v_lines) = tb_v9530; }
    { const char * tb_v9531 = "    snprintf(buf, sizeof buf, \"set_cursor: нет курсора «%s»; есть arrow, hand, text, move, resize_x, resize_y, wait, none\", name);\n"; *(const char * *)tb_grow(v_lines) = tb_v9531; }
    { const char * tb_v9532 = "    tb_crash(line, buf);\n"; *(const char * *)tb_grow(v_lines) = tb_v9532; }
    { const char * tb_v9533 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9533; }
    { const char * tb_v9534 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v9534; }
    { const char * tb_v9535 = "// ---------- для файла .ll (TB_LL): библиотека видна снаружи через tb_x_* ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v9535; }
    { const char * tb_v9536 = "// Сама библиотека — static: так её лучше встраивать. Эти обёртки — её «дверь» для LLVM.\n"; *(const char * *)tb_grow(v_lines) = tb_v9536; }
    { const char * tb_v9537 = "// Без clang (llvm-link + opt + llc) библиотека заранее лежит в файле .bc, а программа\n"; *(const char * *)tb_grow(v_lines) = tb_v9537; }
    { const char * tb_v9538 = "// целиком в .ll: показ значений, конструкторы и main тоже пишутся в .ll.\n"; *(const char * *)tb_grow(v_lines) = tb_v9538; }
    { const char * tb_v9539 = "#if defined(TB_SND) && !defined(TB_BARE)\n"; *(const char * *)tb_grow(v_lines) = tb_v9539; }
    { const char * tb_v9540 = "// ---------- звук: load_sound, play_sound, play_sound_at, listener ... ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v9540; }
    { const char * tb_v9541 = "// Микшер: 48 000 кадров в секунду, стерео, числа float, блоки по 10 мс.\n"; *(const char * *)tb_grow(v_lines) = tb_v9541; }
    { const char * tb_v9542 = "// Голос = звук + громкость + высота (+ место в мире для 3D). В 3D: громкость падает с\n"; *(const char * *)tb_grow(v_lines) = tb_v9542; }
    { const char * tb_v9543 = "// расстоянием, сторона (лево/право) слышна по громкости И по задержке между ушами (как у\n"; *(const char * *)tb_grow(v_lines) = tb_v9543; }
    { const char * tb_v9544 = "// настоящей головы), дальнее ухо и звук сзади глуше (тень головы), воздух глушит высокие\n"; *(const char * *)tb_grow(v_lines) = tb_v9544; }
    { const char * tb_v9545 = "// у далёких звуков, а движение даёт эффект Доплера. Громкость и место меняются плавно\n"; *(const char * *)tb_grow(v_lines) = tb_v9545; }
    { const char * tb_v9546 = "// внутри блока — без щелчков. На выходе ограничитель: сколько звуков ни играй, не трещит.\n"; *(const char * *)tb_grow(v_lines) = tb_v9546; }
    { const char * tb_v9547 = "// Куда идёт звук: Mac — AudioQueue, Linux — ALSA, Windows — waveOut (библиотеки грузятся при\n"; *(const char * *)tb_grow(v_lines) = tb_v9547; }
    { const char * tb_v9548 = "// запуске; нет их — тишина, программа работает). TB_SOUND_FILE=путь.wav — в файл (проверки),\n"; *(const char * *)tb_grow(v_lines) = tb_v9548; }
    { const char * tb_v9549 = "// TB_SOUND=0 — никуда (время идёт, звуки «играют» молча).\n"; *(const char * *)tb_grow(v_lines) = tb_v9549; }
    { const char * tb_v9550 = "#ifndef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v9550; }
    { const char * tb_v9551 = "#include <dlfcn.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v9551; }
    { const char * tb_v9552 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v9552; }
    { const char * tb_v9553 = "#define TB_SR 48000\n"; *(const char * *)tb_grow(v_lines) = tb_v9553; }
    { const char * tb_v9554 = "#define TB_SBLOCK 480\n"; *(const char * *)tb_grow(v_lines) = tb_v9554; }
    { const char * tb_v9555 = "#define TB_NVOICE 64\n"; *(const char * *)tb_grow(v_lines) = tb_v9555; }
    { const char * tb_v9556 = "typedef struct { float *d; long long n; int ch; double rate; int temp; } tb_snd;\n"; *(const char * *)tb_grow(v_lines) = tb_v9556; }
    { const char * tb_v9557 = "typedef struct {\n"; *(const char * *)tb_grow(v_lines) = tb_v9557; }
    { const char * tb_v9558 = "    int on, gen, snd, loop, is3d, fresh, stop;\n"; *(const char * *)tb_grow(v_lines) = tb_v9558; }
    { const char * tb_v9559 = "    double pos, pitch, vol, x, y, z;\n"; *(const char * *)tb_grow(v_lines) = tb_v9559; }
    { const char * tb_v9560 = "    float gl, gr, lpl, lpr;\n"; *(const char * *)tb_grow(v_lines) = tb_v9560; }
    { const char * tb_v9561 = "    double dl, dr, lastd, dop;\n"; *(const char * *)tb_grow(v_lines) = tb_v9561; }
    { const char * tb_v9562 = "} tb_voice;\n"; *(const char * *)tb_grow(v_lines) = tb_v9562; }
    { const char * tb_v9563 = "static tb_snd *tb_snds;\n"; *(const char * *)tb_grow(v_lines) = tb_v9563; }
    { const char * tb_v9564 = "static int tb_nsnd;\n"; *(const char * *)tb_grow(v_lines) = tb_v9564; }
    { const char * tb_v9565 = "static tb_voice tb_voices[TB_NVOICE];\n"; *(const char * *)tb_grow(v_lines) = tb_v9565; }
    { const char * tb_v9566 = "static pthread_mutex_t tb_slock = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v9566; }
    { const char * tb_v9567 = "// слушатель: где он, вектор «вправо», вектор «вперёд» (как у camera)\n"; *(const char * *)tb_grow(v_lines) = tb_v9567; }
    { const char * tb_v9568 = "static double tb_lis[9] = { 0, 0, 0, 1, 0, 0, 0, 0, 1 };\n"; *(const char * *)tb_grow(v_lines) = tb_v9568; }
    { const char * tb_v9569 = "static double tb_master = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9569; }
    { const char * tb_v9570 = "static float tb_mg = 1, tb_lim = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9570; }
    { const char * tb_v9571 = "static int tb_snd_started;\n"; *(const char * *)tb_grow(v_lines) = tb_v9571; }
    { const char * tb_v9572 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v9572; }
    { const char * tb_v9573 = "TB_INL float tb_sget(const tb_snd *s, long long i, int c, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9573; }
    { const char * tb_v9574 = "    if (i < 0 || i >= s->n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9574; }
    { const char * tb_v9575 = "        if (!loop || s->n == 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9575; }
    { const char * tb_v9576 = "        i %= s->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v9576; }
    { const char * tb_v9577 = "        if (i < 0) i += s->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v9577; }
    { const char * tb_v9578 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9578; }
    { const char * tb_v9579 = "    return s->d[i * s->ch + (c < s->ch ? c : 0)];\n"; *(const char * *)tb_grow(v_lines) = tb_v9579; }
    { const char * tb_v9580 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9580; }
    { const char * tb_v9581 = "// точка между кадрами звука: кривая Эрмита по 4 соседям (чище, чем прямая между двумя)\n"; *(const char * *)tb_grow(v_lines) = tb_v9581; }
    { const char * tb_v9582 = "TB_INL float tb_sread(const tb_snd *s, double p, int c, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9582; }
    { const char * tb_v9583 = "    double fl = floor(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v9583; }
    { const char * tb_v9584 = "    long long i = (long long)fl;\n"; *(const char * *)tb_grow(v_lines) = tb_v9584; }
    { const char * tb_v9585 = "    float t = (float)(p - fl);\n"; *(const char * *)tb_grow(v_lines) = tb_v9585; }
    { const char * tb_v9586 = "    float a = tb_sget(s, i - 1, c, loop), b = tb_sget(s, i, c, loop), cc = tb_sget(s, i + 1, c, loop), d = tb_sget(s, i + 2, c, loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v9586; }
    { const char * tb_v9587 = "    float c1 = 0.5f * (cc - a), c2 = a - 2.5f * b + 2 * cc - 0.5f * d, c3 = 0.5f * (d - a) + 1.5f * (b - cc);\n"; *(const char * *)tb_grow(v_lines) = tb_v9587; }
    { const char * tb_v9588 = "    return ((c3 * t + c2) * t + c1) * t + b;\n"; *(const char * *)tb_grow(v_lines) = tb_v9588; }
    { const char * tb_v9589 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9589; }
    { const char * tb_v9590 = "TB_INL float tb_smono(const tb_snd *s, double p, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9590; }
    { const char * tb_v9591 = "    if (s->ch > 1) return 0.5f * (tb_sread(s, p, 0, loop) + tb_sread(s, p, 1, loop));\n"; *(const char * *)tb_grow(v_lines) = tb_v9591; }
    { const char * tb_v9592 = "    return tb_sread(s, p, 0, loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v9592; }
    { const char * tb_v9593 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9593; }
    { const char * tb_v9594 = "// голос кончился: временный звук (play_tone) больше не нужен\n"; *(const char * *)tb_grow(v_lines) = tb_v9594; }
    { const char * tb_v9595 = "static void tb_voice_end(tb_voice *v) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9595; }
    { const char * tb_v9596 = "    v->on = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9596; }
    { const char * tb_v9597 = "    tb_snd *s = &tb_snds[v->snd];\n"; *(const char * *)tb_grow(v_lines) = tb_v9597; }
    { const char * tb_v9598 = "    if (s->temp && s->d) { free(s->d); s->d = 0; s->n = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9598; }
    { const char * tb_v9599 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9599; }
    { const char * tb_v9600 = "// куда и как громко слышен 3D-голос: громкость ушей, задержка ушей, фильтры, Доплер\n"; *(const char * *)tb_grow(v_lines) = tb_v9600; }
    { const char * tb_v9601 = "static void tb_voice_3d(tb_voice *v, float *tl, float *tr, double *tdl, double *tdr, float *fl, float *fr) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9601; }
    { const char * tb_v9602 = "    double dx = v->x - tb_lis[0], dy = v->y - tb_lis[1], dz = v->z - tb_lis[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v9602; }
    { const char * tb_v9603 = "    double d = sqrt(dx * dx + dy * dy + dz * dz);\n"; *(const char * *)tb_grow(v_lines) = tb_v9603; }
    { const char * tb_v9604 = "    double side = 0, front = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9604; }
    { const char * tb_v9605 = "    if (d > 1e-9) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9605; }
    { const char * tb_v9606 = "        side = (dx * tb_lis[3] + dy * tb_lis[4] + dz * tb_lis[5]) / d;\n"; *(const char * *)tb_grow(v_lines) = tb_v9606; }
    { const char * tb_v9607 = "        front = (dx * tb_lis[6] + dy * tb_lis[7] + dz * tb_lis[8]) / d;\n"; *(const char * *)tb_grow(v_lines) = tb_v9607; }
    { const char * tb_v9608 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9608; }
    { const char * tb_v9609 = "    if (d < 0.25) { side *= d / 0.25; front = 1; }   // звук «в голове» — по центру\n"; *(const char * *)tb_grow(v_lines) = tb_v9609; }
    { const char * tb_v9610 = "    double g = d <= 1 ? 1 : 1 / d;                    // громкость падает с расстоянием\n"; *(const char * *)tb_grow(v_lines) = tb_v9610; }
    { const char * tb_v9611 = "    double a = (side + 1) * 0.7853981633974483;      // стороны с равной мощностью\n"; *(const char * *)tb_grow(v_lines) = tb_v9611; }
    { const char * tb_v9612 = "    *tl = (float)(v->vol * g * cos(a) * 1.4142135623730951);\n"; *(const char * *)tb_grow(v_lines) = tb_v9612; }
    { const char * tb_v9613 = "    *tr = (float)(v->vol * g * sin(a) * 1.4142135623730951);\n"; *(const char * *)tb_grow(v_lines) = tb_v9613; }
    { const char * tb_v9614 = "    double itd = 0.00066 * TB_SR * fabs(side);        // до 0,66 мс между ушами\n"; *(const char * *)tb_grow(v_lines) = tb_v9614; }
    { const char * tb_v9615 = "    *tdl = side > 0 ? itd : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9615; }
    { const char * tb_v9616 = "    *tdr = side < 0 ? itd : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9616; }
    { const char * tb_v9617 = "    double fc = 20000 / (1 + d * 0.03);               // воздух: далёкие звуки глуше\n"; *(const char * *)tb_grow(v_lines) = tb_v9617; }
    { const char * tb_v9618 = "    if (front < 0) fc *= 1 - 0.35 * -front;           // сзади глуше\n"; *(const char * *)tb_grow(v_lines) = tb_v9618; }
    { const char * tb_v9619 = "    double fs = fc * (1 - 0.65 * fabs(side));         // дальнее ухо в тени головы\n"; *(const char * *)tb_grow(v_lines) = tb_v9619; }
    { const char * tb_v9620 = "    double cl = side > 0 ? fs : fc, cr = side < 0 ? fs : fc;\n"; *(const char * *)tb_grow(v_lines) = tb_v9620; }
    { const char * tb_v9621 = "    *fl = (float)(1 - exp(-6.283185307179586 * cl / TB_SR));\n"; *(const char * *)tb_grow(v_lines) = tb_v9621; }
    { const char * tb_v9622 = "    *fr = (float)(1 - exp(-6.283185307179586 * cr / TB_SR));\n"; *(const char * *)tb_grow(v_lines) = tb_v9622; }
    { const char * tb_v9623 = "    // Доплер: как быстро звук приближается (расстояние за блок 10 мс), звук летит 343 ед/с\n"; *(const char * *)tb_grow(v_lines) = tb_v9623; }
    { const char * tb_v9624 = "    double want = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9624; }
    { const char * tb_v9625 = "    if (!v->fresh) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9625; }
    { const char * tb_v9626 = "        double sp = (d - v->lastd) * TB_SR / TB_SBLOCK;\n"; *(const char * *)tb_grow(v_lines) = tb_v9626; }
    { const char * tb_v9627 = "        if (fabs(sp) < 686) want = 343 / (343 + sp);   // быстрее — это прыжок, не движение\n"; *(const char * *)tb_grow(v_lines) = tb_v9627; }
    { const char * tb_v9628 = "        if (want < 0.5) want = 0.5;\n"; *(const char * *)tb_grow(v_lines) = tb_v9628; }
    { const char * tb_v9629 = "        if (want > 2) want = 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v9629; }
    { const char * tb_v9630 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9630; }
    { const char * tb_v9631 = "    v->dop = v->fresh ? 1 : v->dop * 0.8 + want * 0.2;\n"; *(const char * *)tb_grow(v_lines) = tb_v9631; }
    { const char * tb_v9632 = "    v->lastd = d;\n"; *(const char * *)tb_grow(v_lines) = tb_v9632; }
    { const char * tb_v9633 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9633; }
    { const char * tb_v9634 = "// смешать n кадров всех голосов в out (стерео, по очереди лево-право)\n"; *(const char * *)tb_grow(v_lines) = tb_v9634; }
